(function(w){var a=w.BVC_PASSAGE_RESEARCH_CONTENT=w.BVC_PASSAGE_RESEARCH_CONTENT||[];[{"schema":"JBC_PASSAGE_READER_COMMENTARY_v1","researchId":"JER_001_001_010_WORBS_READER_DRAFT_20261017","researchType":"WORBS","researchDepth":"CORE","sourcePath":"G:/내 드라이브/Jude_Lee_OS/01_PROJECTS/01_목회연구_WORBS_BICS/WORKING_COMMENTARY66_20261011/JER_001_001_010_WORBS_READER_DRAFT_20261017.md","sourceSha256":"229abadb623febed2f0bb3b886e30785336ab9fa5bf6f7704d8dff8be6b506a4","passage":{"book":"jer","chapter":1,"v1":1,"v2":10,"ref":"예레미야 1:1–10"},"projectionStatus":"INTERNAL_READER_PROJECTION","professionalStatus":"CANDIDATE_REVIEW_ONLY","qualityStatus":"CANDIDATE_RESEARCH_REVIEW_REQUIRED","externalRelease":"NOT_AUTHORIZED","generatedByProject":"01_목회연구_WORBS_BICS","professionalAuthorityOwner":"01_목회연구_WORBS_BICS","title":"한 사람의 입에 맡겨진 열방을 향한 말씀","overview":["예레미야서는 한 선지자의 생애를 소개하는 동시에 그의 말이 누구에게서 왔으며 어떤 시대를 관통하는지 밝힙니다. 아나돗 출신 제사장 가문의 예레미야는 유다 왕국이 쇠퇴하고 예루살렘이 무너지는 긴 시간 동안 말씀을 받습니다. 하나님은 그를 역사적 위기 속에서 급히 발탁한 사람으로만 말씀하지 않으십니다. 태어나기 전부터 아셨고 구별하셨으며 열방을 향한 선지자로 세우셨다고 선언하십니다. 예레미야가 자신의 말할 능력을 문제 삼을 때 하나님은 그의 재능을 칭찬하는 대신, 보내시는 분의 권위와 함께하심을 약속하십니다."],"centralMessage":"이 소명 장면은 뒤에 이어질 심판 선포와 회복 약속을 함께 여는 문입니다. 그의 입에 주어진 말씀은 뽑고 허무는 말씀이면서 동시에 세우고 심는 말씀입니다. 이 본문을 개인의 성공이나 잠재력을 확인하는 격언으로 읽으면, 유다와 열방을 향해 말씀하시는 하나님의 역사적·언약적 목적이 사라집니다.","literaryStructure":[{"v1":1,"v2":3,"title":"말씀을 받은 사람과 무너져 가는 왕국"},{"v1":4,"v2":5,"title":"태중보다 앞선 하나님의 앎과 구별하심"},{"v1":6,"v2":8,"title":"‘나는 말할 줄 모릅니다’라는 응답"},{"v1":9,"v2":10,"title":"입에 닿은 손과 여섯 개의 사명 동사"}],"sections":[{"id":"jer1-1-3","v1":1,"v2":3,"title":"말씀을 받은 사람과 무너져 가는 왕국","paragraphs":["책은 ‘예레미야의 말’이라는 소개로 열리지만 곧 그에게 ‘여호와의 말씀’이 임했다고 밝힙니다. 인간의 목소리와 하나님의 말씀이 분리되지 않으면서도 혼동되지 않는 구조입니다. 예레미야가 자신의 경험과 고통을 말할 것이지만, 이 책은 그 경험 자체를 최종 권위로 삼지 않습니다. 그가 받아 전한 말씀이 역사에 대한 해석의 중심을 이룹니다.","예레미야는 베냐민 땅 아나돗의 제사장들 가운데 속한 힐기야의 아들로 소개됩니다. 아나돗은 예루살렘과 가까운 베냐민 지역의 정착지이며 제사장 전통과 연결된 장소입니다(수 21:18; 왕상 2:26). 그는 성전과 제사장 제도를 전혀 모르는 외부 비판자가 아니었습니다. 그러나 본문은 그의 아버지 힐기야를 요시야 시대에 율법책을 발견한 대제사장 힐기야(왕하 22장)와 동일 인물이라고 말하지 않습니다. 같은 이름만으로 두 사람을 합쳐서는 안 됩니다.","시간 표지는 요시야 재위 제13년에서 시작해 여호야김 시대를 거쳐 시드기야 제11년, 예루살렘 주민이 사로잡혀 가는 다섯째 달에 이릅니다. 요시야 제13년은 통상 기원전 627/626년 무렵으로 계산되지만 왕의 재위 연도 산정 방식에 따라 차이가 있습니다. 마지막 사건은 기원전 587/586년의 예루살렘 멸망과 연결됩니다. 머리말은 왕이 바뀌어도 예레미야에게 임한 말씀이 지속되었음을 보여 줍니다. 여호아하스와 여호야긴의 짧은 통치가 이 요약에 빠졌다고 해서 그들이 역사에 존재하지 않았다는 뜻은 아닙니다.","서두가 제시하는 역사의 끝은 정치적 승리가 아니라 유배입니다. 독자는 예레미야가 처음 부름받는 장면을 읽으면서도 이미 그 사역이 얼마나 아픈 결말을 향할지 알고 있습니다. 따라서 뒤따르는 소명은 장래가 보장된 영웅의 출발이 아니라 거부와 심판의 시간을 통과할 말씀 사역의 시작으로 들립니다."]},{"id":"jer1-4-5","v1":4,"v2":5,"title":"태중보다 앞선 하나님의 앎과 구별하심","paragraphs":["4절의 ‘여호와의 말씀이 내게 임했다’는 표현은 연대기적 소개에서 직접적인 소명 대화로 장면을 전환합니다. 하나님은 예레미야의 이력이나 자격을 먼저 묻지 않으시고 자신의 행위를 밝히십니다. 빚기 전에 아셨고, 태에서 나오기 전에 구별하셨으며, 열방의 선지자로 세우셨습니다. ‘알다’에 해당하는 히브리어 **יָדַע**(야다)는 여기서 단순히 미래 정보를 미리 파악했다는 뜻에 머물지 않습니다. 이어지는 ‘구별하다’와 ‘세우다’가 보여 주듯, 하나님이 한 사람을 자기 목적 안에서 인정하고 관계적으로 선택하셨다는 뜻을 품습니다.","‘거룩하게 하다/구별하다’의 **קָדַשׁ**(카다쉬) 계열 표현도 예레미야가 태어날 때부터 도덕적으로 완전했다는 선언이 아닙니다. 하나님이 그를 특별한 말씀의 직무에 속하도록 정하셨다는 뜻입니다. ‘열방의 선지자’라는 임명은 유다 안에서만 일어날 일을 넘어서는 지평을 열어 줍니다. 예레미야의 활동 무대는 주로 유다였지만, 그의 말씀은 제국과 열방의 흥망, 하나님의 심판과 회복을 다룹니다(렘 25장; 46–51장). ‘열방’은 모든 나라를 직접 방문해야 한다는 여행 명령이 아닙니다.","이 구절을 모든 개인의 진로나 성공이 태어나기 전에 세부적으로 결정되었다는 일반 명제로 곧바로 확대할 수는 없습니다. 본문이 직접 말하는 것은 예레미야라는 특정 선지자의 소명입니다. 동시에 그 소명의 기원은 인간의 능력보다 하나님의 먼저 아심과 부르심에 놓여 있습니다. 역사 한가운데 들리는 예언의 말씀이 어디에서 권위를 얻는지 밝히는 장면입니다."]},{"id":"jer1-6-8","v1":6,"v2":8,"title":"‘나는 말할 줄 모릅니다’라는 응답","paragraphs":["예레미야는 ‘아, 주 여호와여’라는 탄식 섞인 말로 대답합니다. 그는 말을 잘하지 못하며 자신이 **נַעַר**(나아르), 곧 ‘어린 사람/젊은이’라고 말합니다. 이 말은 경험과 사회적 권위가 부족하다는 자기 인식을 나타내지만 정확한 나이를 계산해 주지는 않습니다. 그를 반드시 십대 소년이라고 단정할 근거는 이 절만으로 충분하지 않습니다.","하나님의 응답은 예레미야의 자기평가를 장황하게 반박하지 않습니다. ‘나는 어리다’고 말하지 말라고 하시면서, 보내시는 곳으로 가고 명령하시는 말을 전해야 한다고 하십니다. 반복되는 ‘모든’은 선지자가 자신의 선호에 따라 청중과 메시지를 고를 수 없음을 강조합니다. 선지자의 정체성은 독창적인 의견을 내는 능력보다 자신을 보내신 분의 말씀에 충실한 사절의 위치에서 형성됩니다.","이어지는 ‘두려워하지 말라’는 명령에는 ‘내가 너와 함께하여 너를 구원하겠다’는 약속이 붙습니다. 여기서 구원은 반대와 고통 자체가 없어질 것이라는 보증이 아닙니다. 예레미야서는 그가 말씀 때문에 위협과 감금, 모욕을 당하는 모습을 길게 기록합니다. 함께하심의 약속은 위험이 없다는 선언이 아니라 위험 속에서도 말씀을 맡기신 하나님이 선지자를 버리지 않으신다는 근거입니다. 모세가 자신의 말솜씨를 문제 삼았던 출애굽기 4장과 공명하지만 두 인물의 소명과 역사적 역할을 하나로 합칠 필요는 없습니다."]},{"id":"jer1-9-10","v1":9,"v2":10,"title":"입에 닿은 손과 여섯 개의 사명 동사","paragraphs":["9절에서 하나님은 손을 내밀어 예레미야의 입에 대십니다. 이어 ‘내 말을 네 입에 두었다’고 말씀하십니다. 이 장면은 선지자가 자신의 언변을 훈련해 신적 권위를 획득했다는 이야기가 아닙니다. 말씀의 기원이 하나님께 있고 예레미야의 입은 그 말씀을 전할 도구가 되었다는 상징적 행위입니다. 신명기 18:18의 ‘내 말을 그의 입에 두리라’는 약속과도 연결되며, 이사야 6장의 입술 정결 장면과는 다른 방식으로 예언자의 입과 하나님의 말씀을 결합합니다.","10절의 여섯 동사는 사명의 규모와 성격을 밝힙니다. ‘뽑고, 파괴하고, 멸하고, 넘어뜨리고’라는 네 표현 뒤에 ‘세우고, 심는다’는 두 표현이 옵니다. 첫 네 동사의 집중은 죄와 거짓 안전에 대한 심판의 무게를 드러냅니다. 그러나 마지막 두 동사가 빠지면 예레미야의 사역을 파괴의 예언으로만 축소하게 됩니다. 이 배열은 책 전체를 해석하는 열쇠입니다. 하나님은 훗날 ‘뽑고 무너뜨리는 것’과 ‘세우고 심는 것’을 다시 함께 말씀하십니다(렘 18:7–10; 31:28).","‘열방과 왕국들 위에 세웠다’는 말도 예레미야에게 직접적인 정치 통치권이나 군사 권한을 부여했다는 뜻은 아닙니다. 그가 선포할 하나님의 말씀이 왕국들의 미래를 판정하고 해석할 권위를 지닌다는 예언적 표현입니다. 유다의 성전과 왕권이 안전을 보증해 주지 못하는 시대에, 이 말씀은 제국보다 작은 한 선지자의 입을 통해 역사의 참된 주권자가 누구인지 밝힙니다."]}],"lexicalCards":[],"discoveries":[],"canonicalLinks":[],"theologicalSynthesis":[],"alternativeReadings":[{"title":"‘말’과 ‘말씀’의 문학적 틀","paragraphs":["1절의 예레미야의 ‘말들’과 2·4절의 ‘여호와의 말씀’은 책 전체의 목소리를 설정합니다. 이 책은 예레미야의 인격과 감정을 지우지 않으면서도 그가 전하는 신탁을 하나님의 말씀으로 듣도록 독자를 이끕니다. 이후의 탄식과 논쟁도 이 긴장 속에서 읽어야 합니다."]},{"title":"히브리어 동사의 시간과 소명","paragraphs":["5절의 ‘알았다–구별했다–세웠다’는 하나님이 먼저 행하신 일을 선언합니다. 그러나 이를 현대 철학의 모든 예정론 논쟁에 대한 직접 답으로 옮기면 본문의 소명 담화를 넘어섭니다. 문장 속에서 중요한 것은 예레미야가 자신을 설명하기 전에 하나님이 먼저 그의 사명을 설명하신다는 순서입니다. ‘뽑다’(**נָתַשׁ**, 나타쉬)와 ‘세우다’(**בָּנָה**, 바나), ‘심다’(**נָטַע**, 나타)는 단지 추상적인 가치 평가가 아니라 건물과 식물의 구체적 이미지로 나라들의 무너짐과 회복을 그립니다."]},{"title":"역사적 머리말과 책의 편집","paragraphs":["1:1–3은 수십 년의 사역을 한 번에 바라보는 서문입니다. 이것을 예레미야가 부름받던 바로 그날 자신의 사역 마지막 장면까지 기록했다는 뜻으로 볼 필요는 없습니다. 현존 예레미야서가 그의 말과 역사적 전승을 수집·배열해 독자가 전체 사역을 조망하게 한다는 문학적 기능에 주목하는 것이 안전합니다."]},{"title":"심판과 회복의 비대칭","paragraphs":["10절에서 파괴를 뜻하는 동사가 네 개, 회복을 뜻하는 동사가 두 개라고 해서 하나님의 목적을 ‘심판 3분의 2, 회복 3분의 1’로 계산할 수는 없습니다. 동사의 밀집은 심판의 무게를 부각하고 마지막의 세움과 심음은 심판이 하나님의 최종 말씀 전부가 아님을 밝힙니다. 31장의 새 언약 약속은 이 마지막 두 동사가 펼쳐질 더 넓은 지평입니다."]},{"title":"원문과 번역의 주의점","paragraphs":["6절의 ‘나아르’는 문맥에 따라 어린이·청년·시종 등 다양한 연령과 역할을 가리킬 수 있습니다. 여기서는 선지자가 스스로 내세우는 경험 부족의 표현으로 읽는 것이 적절합니다. 5절의 ‘알다’ 역시 미래 사실을 미리 안다는 뜻으로만 번역하면 ‘구별하고 세운다’는 뒤따르는 관계적·직무적 문맥이 희미해집니다."]}],"relatedResearch":[],"readerSources":[{"name":"Tyndale Open Study Notes","locator":"Tyndale Open Study Notes · Tyndale House Publishers · 예레미야 1:1–19 관련 주해 및 예레미야서 서론, 제공 자료 release 1","license":"CC BY-SA 4.0"}],"notes":["연구 참고자료\n* Open Scriptures Hebrew Bible (OSHB) · Open Scriptures Hebrew Bible Project · 예레미야 1:1–10, 기존 JudeBible 히브리어 본문 v2.2 · CC BY 4.0\n   * 원자료: https://github.com/openscriptures/morphhb\n   * 사용·변경 고지: 히브리어 표현과 어절을 대조해 한국어 문맥 해설을 작성했습니다. JudeBible의 생성된 표시 데이터를 별도 독립 원전 판본이라고 주장하지 않습니다.\n* Westminster Leningrad Codex (WLC) · OSHB의 기반 히브리어 본문 · 예레미야 1장 기반 본문 · Public Domain\n   * 기반 판본 정보: https://github.com/openscriptures/morphhb\n* Open Scriptures Hebrew Lexicon · Open Scriptures Hebrew Bible Project · 예레미야 1:5–10 관련 표제어(ידע, קדש, נער, נתש, בנה, נטע), 검증된 LexicalIndex 원천 자료 · CC BY 4.0\n   * 원자료: https://github.com/openscriptures/HebrewLexicon\n   * 변경·번역 고지: 원천의 영어 짧은 뜻을 실제 확인하고 한국어로 문맥에 맞게 풀이했습니다. 원천 어휘 자료와 별도의 한국어 풀이 자료를 동일한 저작물로 취급하지 않습니다.\n* Tyndale Open Study Notes · Tyndale House Publishers · 예레미야 1:1–19 관련 주해 및 예레미야서 서론, 제공 자료 release 1.25 / Copyright © 2022 Tyndale House Publishers · CC BY-SA 4.0\n   * 원자료: http://www.tyndaleopenresources.com\n   * 저작권자 지정 고지: Adapted from Tyndale Open Study Notes. The original work by Tyndale House Publishers is available for free at http://www.tyndaleopenresources.com.\n   * 변경·번역 고지: 소명 대화의 구조, 왕들의 연대기적 배경, 말씀을 맡은 사절이라는 해석을 참고하여 한국어 문맥 연구로 재구성하고 확장했습니다.\n* Project01 예레미야 Book Profile · Jude Lee OS Project01 · JER_Jeremiah_BOOK_PROFILE_Theological_Filter_v0.2, 문학·신학 필터 · 내부 연구자료(외부 이용허락 별도 확인 필요)\n   * 사용 고지: 심판과 새 언약의 긴장, 소명 본문을 개인 성공담으로 축소하지 않는 독법을 해석적 경계로 참조했습니다.","연구 및 재서술 안내\n이 글은 예레미야 1:1–10의 히브리어 본문과 위에 명시한 실제 열람 자료를 대조해 작성한 한국어 WORBS 주석입니다. 공통 성경 원문 자료(OSHB·WLC·히브리어 어휘 자료), 개별 본문 참고 주석(Tyndale), Project01 내부 문학·신학 필터를 구별했습니다. 원자료의 문장을 연속적으로 번역하지 않고 본문 흐름을 따라 설명을 새롭게 구성했으며 참고·번역·변형 관계를 위에 밝혔습니다. 원고 전체의 독립 저작물 또는 파생 저작물 해당 여부는 여기서 확정하지 않습니다.","라이선스\nOSHB와 Open Scriptures Hebrew Lexicon의 확인된 이용 조건은 CC BY 4.0(https://creativecommons.org/licenses/by/4.0/)이며 그 기반 WLC 본문은 Public Domain으로 식별됩니다. Tyndale Open Study Notes의 확인된 이용 조건은 CC BY-SA 4.0(https://creativecommons.org/licenses/by-sa/4.0/)으로 저작권자 표시·변경 고지·동일조건변경허락 요건을 별도로 검토해야 합니다. Project01 내부 필터의 외부 이용허락은 별도로 확인해야 합니다. 성경전서 개역한글판의 연속 번역문은 인용하지 않았으며 재배포 허락도 가정하지 않습니다. 원고 전체에 적용될 단일 라이선스는 별도 권리 검증 전에 정하지 않습니다."],"sourceNotice":"연구 참고자료\n* Open Scriptures Hebrew Bible (OSHB) · Open Scriptures Hebrew Bible Project · 예레미야 1:1–10, 기존 JudeBible 히브리어 본문 v2.2 · CC BY 4.0\n   * 원자료: https://github.com/openscriptures/morphhb\n   * 사용·변경 고지: 히브리어 표현과 어절을 대조해 한국어 문맥 해설을 작성했습니다. JudeBible의 생성된 표시 데이터를 별도 독립 원전 판본이라고 주장하지 않습니다.\n* Westminster Leningrad Codex (WLC) · OSHB의 기반 히브리어 본문 · 예레미야 1장 기반 본문 · Public Domain\n   * 기반 판본 정보: https://github.com/openscriptures/morphhb\n* Open Scriptures Hebrew Lexicon · Open Scriptures Hebrew Bible Project · 예레미야 1:5–10 관련 표제어(ידע, קדש, נער, נתש, בנה, נטע), 검증된 LexicalIndex 원천 자료 · CC BY 4.0\n   * 원자료: https://github.com/openscriptures/HebrewLexicon\n   * 변경·번역 고지: 원천의 영어 짧은 뜻을 실제 확인하고 한국어로 문맥에 맞게 풀이했습니다. 원천 어휘 자료와 별도의 한국어 풀이 자료를 동일한 저작물로 취급하지 않습니다.\n* Tyndale Open Study Notes · Tyndale House Publishers · 예레미야 1:1–19 관련 주해 및 예레미야서 서론, 제공 자료 release 1.25 / Copyright © 2022 Tyndale House Publishers · CC BY-SA 4.0\n   * 원자료: http://www.tyndaleopenresources.com\n   * 저작권자 지정 고지: Adapted from Tyndale Open Study Notes. The original work by Tyndale House Publishers is available for free at http://www.tyndaleopenresources.com.\n   * 변경·번역 고지: 소명 대화의 구조, 왕들의 연대기적 배경, 말씀을 맡은 사절이라는 해석을 참고하여 한국어 문맥 연구로 재구성하고 확장했습니다.\n* Project01 예레미야 Book Profile · Jude Lee OS Project01 · JER_Jeremiah_BOOK_PROFILE_Theological_Filter_v0.2, 문학·신학 필터 · 내부 연구자료(외부 이용허락 별도 확인 필요)\n   * 사용 고지: 심판과 새 언약의 긴장, 소명 본문을 개인 성공담으로 축소하지 않는 독법을 해석적 경계로 참조했습니다.\n\n연구 및 재서술 안내\n이 글은 예레미야 1:1–10의 히브리어 본문과 위에 명시한 실제 열람 자료를 대조해 작성한 한국어 WORBS 주석입니다. 공통 성경 원문 자료(OSHB·WLC·히브리어 어휘 자료), 개별 본문 참고 주석(Tyndale), Project01 내부 문학·신학 필터를 구별했습니다. 원자료의 문장을 연속적으로 번역하지 않고 본문 흐름을 따라 설명을 새롭게 구성했으며 참고·번역·변형 관계를 위에 밝혔습니다. 원고 전체의 독립 저작물 또는 파생 저작물 해당 여부는 여기서 확정하지 않습니다.\n\n라이선스\nOSHB와 Open Scriptures Hebrew Lexicon의 확인된 이용 조건은 CC BY 4.0(https://creativecommons.org/licenses/by/4.0/)이며 그 기반 WLC 본문은 Public Domain으로 식별됩니다. Tyndale Open Study Notes의 확인된 이용 조건은 CC BY-SA 4.0(https://creativecommons.org/licenses/by-sa/4.0/)으로 저작권자 표시·변경 고지·동일조건변경허락 요건을 별도로 검토해야 합니다. Project01 내부 필터의 외부 이용허락은 별도로 확인해야 합니다. 성경전서 개역한글판의 연속 번역문은 인용하지 않았으며 재배포 허락도 가정하지 않습니다. 원고 전체에 적용될 단일 라이선스는 별도 권리 검증 전에 정하지 않습니다."},{"schema":"JBC_PASSAGE_READER_COMMENTARY_v1","researchId":"JER_001_011_019_WORBS_READER_DRAFT_20261017","researchType":"WORBS","researchDepth":"CORE","sourcePath":"G:/내 드라이브/Jude_Lee_OS/01_PROJECTS/01_목회연구_WORBS_BICS/WORKING_COMMENTARY66_20261011/JER_001_011_019_WORBS_READER_DRAFT_20261017.md","sourceSha256":"266a9adbe614a74a87d4f20ff067f65c3cc0cdfba3e1fb10609218d77ca7bd73","passage":{"book":"jer","chapter":1,"v1":11,"v2":19,"ref":"예레미야 1:11–19"},"projectionStatus":"INTERNAL_READER_PROJECTION","professionalStatus":"CANDIDATE_REVIEW_ONLY","qualityStatus":"CANDIDATE_RESEARCH_REVIEW_REQUIRED","externalRelease":"NOT_AUTHORIZED","generatedByProject":"01_목회연구_WORBS_BICS","professionalAuthorityOwner":"01_목회연구_WORBS_BICS","title":"깨어 지키시는 말씀과 북쪽에서 기울어지는 가마","overview":["예레미야의 소명은 입에 말씀을 받는 것으로 끝나지 않습니다. 하나님은 그가 본 것을 묻고, 두 차례의 환상을 해석해 주시며, 마침내 두려운 반대 속에서도 말씀을 전하도록 명령하십니다. 첫 환상인 살구나무 가지는 하나님이 자신의 말씀을 깨어 지켜 반드시 이루신다는 확신을 줍니다. 두 번째 환상인 북쪽에서 기울어진 끓는 가마는 그 말씀이 유다에 닥칠 재앙과 심판의 형태로 역사 안에 들어올 것임을 보여 줍니다."],"centralMessage":"이 두 환상 사이에는 중요한 긴장이 있습니다. 하나님이 말씀을 지키신다는 사실은 곧바로 편안한 미래를 뜻하지 않습니다. 말씀의 성취에는 우상숭배와 불의에 대한 심판도 포함됩니다. 그래서 하나님은 예레미야를 모든 사람에게 환영받는 인물이 아니라, 왕과 지도자와 제사장과 백성의 저항 앞에 서야 할 말씀의 증인으로 세우십니다. ‘그들이 너를 이기지 못한다’는 약속은 고난의 부재가 아니라 그 고난 속에서도 하나님이 자신의 사절을 버리지 않으신다는 선언입니다.","literaryStructure":[{"v1":11,"v2":12,"title":"살구나무 가지: 보이는 것에서 들리는 말씀으로"},{"v1":13,"v2":14,"title":"북쪽에서 기울어지는 끓는 가마"},{"v1":15,"v2":16,"title":"성문 앞에 놓일 왕좌들과 심판의 이유"},{"v1":17,"v2":17,"title":"허리를 동이고 말하라: 위협 앞에 세워진 증인"},{"v1":18,"v2":19,"title":"견고한 성읍과 놋 성벽의 역설"}],"sections":[{"id":"jer1-11-12","v1":11,"v2":12,"title":"살구나무 가지: 보이는 것에서 들리는 말씀으로","paragraphs":["첫 장면은 ‘네가 무엇을 보느냐’라는 하나님의 질문으로 시작합니다. 예레미야는 ‘살구나무 가지’를 본다고 대답합니다. 환상 자체는 복잡하지 않습니다. 그저 가지 하나입니다. 그런데 하나님은 그가 제대로 보았다고 하신 뒤, 자신이 말씀을 지켜 이루겠다고 설명하십니다. 이 연결은 히브리어의 소리 유사성에 기초합니다. ‘살구나무’를 가리키는 **שָׁקֵד**(샤케드)와 ‘깨어 지켜보다’를 뜻하는 **שֹׁקֵד**(쇼케드)가 가까운 소리로 울립니다. 한국어 번역에서는 두 단어의 연결이 쉽게 사라지지만, 원문에서는 한 단어가 다른 단어를 기억하게 하는 예언적 언어유희가 됩니다.","살구나무는 이 지역에서 비교적 이른 시기에 꽃을 피우는 나무이므로 깨어 있음의 이미지와도 어울립니다. 그러나 환상의 결정적 뜻은 식물학적 계절표가 아니라 하나님이 직접 주시는 해석에 있습니다. 하나님이 ‘깨어 지키시는’ 대상은 우선 **자신의 말씀**입니다. 이 말씀을 예레미야 개인의 무사함을 보장하는 표지로만 축소해서는 안 됩니다. 뒤이어 선포될 심판과 회복 모두가 하나님의 말씀이기 때문입니다.","첫 환상은 선지자의 권위를 그가 특별한 미래 예측 능력을 소유했다는 데 두지 않습니다. 예레미야는 본 것을 보고하고, 하나님이 그 의미를 설명하십니다. 환상을 보는 일과 그 뜻을 정하는 일이 구별됩니다. 하나님의 해석이 주어지기 전까지 단순한 나뭇가지를 정치 사건의 암호로 자의적으로 해독할 수 없다는 점도 이 구조에서 드러납니다."]},{"id":"jer1-13-14","v1":13,"v2":14,"title":"북쪽에서 기울어지는 끓는 가마","paragraphs":["두 번째 질문에서도 하나님은 ‘무엇을 보느냐’고 물으십니다. 예레미야가 본 것은 불에 달궈지거나 끓는 가마이며, 그 가마가 북쪽 방향과 관련된 기울어진 모습으로 묘사됩니다. 히브리어의 방향 표현은 가마가 정확히 어느 각도로 기울어져 있는지 현대 지도 위에 그릴 만큼 상세하지 않습니다. 중요한 것은 하나님이 곧바로 해석을 주신다는 사실입니다. 북쪽으로부터 재앙이 터져 나와 이 땅의 주민에게 닥칠 것입니다.","고대 유다의 지리에서 ‘북쪽’은 단순한 나침반의 방향을 넘어 침입과 군대 이동의 주요 접근 방향을 가리킬 수 있습니다. 메소포타미아의 강대국이 유다로 진군할 때 그 사이의 건조한 광야를 곧장 가로지르기보다 유프라테스 상류와 시리아·레반트의 교통권을 따라 접근하는 경로가 중요했기 때문입니다. 다만 이 본문만으로 특정 고대 도로의 좌표나 모든 군대의 실제 이동 경로를 복원할 수는 없습니다.","예레미야서의 후속 역사에서 북쪽의 심판 세력은 바벨론과 분명하게 연결됩니다. 그러나 이 첫 환상의 시점에 독자가 이미 모든 군사적 세부와 정치적 변화를 안다고 가정해서는 안 됩니다. 환상은 먼저 유다의 안전을 뒤흔들 하나님의 심판이 외부 세력의 침입이라는 역사적 사건으로 다가올 것임을 알립니다. 첫 환상의 ‘말씀을 지키심’은 두 번째 환상의 ‘재앙’과 연결되어, 성취의 확실성이 반드시 듣기 좋은 소식만을 의미하지 않음을 드러냅니다."]},{"id":"jer1-15-16","v1":15,"v2":16,"title":"성문 앞에 놓일 왕좌들과 심판의 이유","paragraphs":["15절에서 하나님은 ‘북쪽 왕국들의 모든 족속’을 부르겠다고 하십니다. 이 표현은 재앙이 단순한 자연현상이나 막연한 불운이 아니라, 정치적·군사적 행위자들을 통해 유다에 도달할 것을 보여 줍니다. 그들이 와서 예루살렘 성문 어귀에 각자의 왕좌를 놓고, 성벽과 유다 성읍들을 압박하는 모습은 도시의 공적 권위가 적대 세력에 의해 침범당하는 장면입니다. 성문은 단순한 출입구가 아니라 재판과 통치, 공동체의 공적 삶이 이루어지는 장소였으므로, 그 앞에 외국 왕좌가 놓인다는 이미지는 왕국의 주권과 질서가 무너지는 위협을 압축합니다.","그런데 하나님은 그 위협을 설명하면서 곧바로 ‘그들의 모든 악’을 언급하십니다. 유다가 다른 신들에게 분향하고 자기 손으로 만든 것에 절했다는 사실이 심판의 이유로 제시됩니다. 여기서 핵심은 군사력이 약해서 패배한다는 정치적 분석만이 아닙니다. 언약 공동체가 하나님을 버리고 피조물과 인간이 만든 대상에 예배의 자리를 내준 것이 본문이 밝히는 신학적 원인입니다. 우상숭배는 내면의 취향 차이가 아니라 공동체의 충성과 삶의 질서를 왜곡하는 언약 배반으로 해석됩니다.","16절의 ‘내가 그들에게 심판을 말하겠다’는 표현은 앞선 소명에서 하나님이 예레미야의 입에 말씀을 두셨다는 선언과 연결됩니다. 선지자는 독자적인 고발자가 아니라 하나님의 판결을 전하는 증인입니다. 그렇다고 군사적 침공 자체를 오늘날의 모든 전쟁과 기계적으로 동일시해 하나님의 심판이라고 선언할 권한이 이 본문에서 생기지는 않습니다. 여기서는 하나님이 예레미야에게 특정 역사 상황에 대한 해석을 직접 주셨다는 점이 결정적입니다."]},{"id":"jer1-17-17","v1":17,"v2":17,"title":"허리를 동이고 말하라: 위협 앞에 세워진 증인","paragraphs":["환상 해석 뒤에 하나님은 예레미야 자신에게 명령하십니다. ‘허리를 동이라’는 표현은 긴 옷자락을 정리하여 움직일 준비를 하는 고대의 관용적 이미지입니다. 예레미야는 보고 들은 것을 마음속에만 간직할 수 없습니다. 일어나 명령받은 모든 것을 전해야 합니다. 환상은 선지자의 호기심을 채우기 위한 사적인 계시가 아니라 공개적인 말씀 선포로 이어집니다.","하나님은 사람들 앞에서 두려워하지 말라고 하시면서, 두려움에 굴복하면 오히려 그들 앞에서 무너지게 하시겠다고 경고하십니다. 이는 선지자의 감정에 두려움이 조금이라도 생기면 곧 실패한다는 심리 규칙이 아닙니다. 하나님께 받은 말을 사람의 반응에 맞추어 바꾸거나 침묵하는 일이 소명의 본질을 거스른다는 엄중한 명령입니다. 1:7의 ‘명령하는 모든 말을 하라’가 여기서 다시 울립니다."]},{"id":"jer1-18-19","v1":18,"v2":19,"title":"견고한 성읍과 놋 성벽의 역설","paragraphs":["마지막 장면에서 하나님은 예레미야를 ‘견고한 성읍’, ‘쇠기둥’, ‘놋 성벽’으로 세우셨다고 말씀하십니다. 서로 다른 건축·방어 이미지가 겹치면서 강력한 저항에도 무너지지 않을 선지자의 사명을 그립니다. 그러나 이 약속은 예레미야가 실제로 성을 지키는 군사 지도자가 되거나 사람들에게 물리적 위해를 가해도 된다는 허가가 아닙니다. 말씀을 맡은 사람의 견고함을 상징적으로 표현한 것입니다.","그를 대적할 이들은 유다의 왕들, 지도자들, 제사장들, 그 땅의 백성으로 열거됩니다. 왕권과 정치 지도층뿐 아니라 제의의 권위와 일반 공동체까지 반대의 범위에 들어갑니다. 아나돗의 제사장 집안에서 나온 사람이 제사장들을 포함한 온 사회와 충돌해야 한다는 점은 소명의 고통을 더 선명하게 합니다. 하나님의 말씀은 기존의 종교적 권위가 말하는 것과 언제나 같은 내용일 것이라는 기대가 이 자리에서 깨집니다.","‘그들이 너를 치나 이기지 못한다’는 약속 뒤에는 다시 ‘내가 너와 함께하여 너를 구원한다’는 말씀이 따라옵니다. 8절의 약속이 19절에서 되풀이되면서 소명 장면을 감쌉니다. 이 약속을 읽는 독자는 이후 예레미야가 매를 맞고 갇히고 위협받는 장면들(렘 20장; 37–38장)을 만나게 됩니다. 그 사건들은 약속이 거짓이었다는 증거가 아니라, 하나님의 동행이 고난의 제거와 같지 않다는 사실을 보여 줍니다. 예레미야가 보존되는 이유는 자신의 강인함을 과시하기 위해서가 아니라, 그에게 맡겨진 말씀이 끝까지 전해져야 하기 때문입니다."]}],"lexicalCards":[],"discoveries":[],"canonicalLinks":[],"theologicalSynthesis":[],"alternativeReadings":[{"title":"살구나무와 지켜보심의 언어유희","paragraphs":["11절의 명사 **שָׁקֵד**(샤케드, 살구나무)와 12절의 분사 **שֹׁקֵד**(쇼케드, 깨어 지키는)는 서로 다른 어휘 기능을 지니면서도 유사한 소리를 공유합니다. 이 소리의 결합은 우연한 식물 관찰을 신탁의 핵심 주제로 전환합니다. 분사는 하나님이 말씀을 지켜보고 계신다는 지속적인 태도를 생생하게 표현합니다. 다만 살구나무가 다른 나무보다 먼저 꽃핀다는 자연 관찰만으로 ‘예언이 즉시 실현된다’는 시간표를 만들 수는 없습니다. 하나님의 해석은 성취의 확실성을 말하지만 날짜를 지정하지 않습니다."]},{"title":"북쪽의 지리와 역사","paragraphs":["예루살렘에서 볼 때 바벨론의 중심부는 동쪽에 가깝습니다. 그럼에도 북쪽으로부터의 침입이라는 표현이 성립하는 것은 레반트로 진군하는 메소포타미아 세력이 사막을 직선으로 가로지르기보다 북부 시리아와 유프라테스 유역의 통행 가능한 길을 이용할 수 있었기 때문입니다. 이는 고대 지리의 일반적인 이동 조건을 설명할 뿐, 1:13의 가마가 실제 특정 군대의 행군로를 지도에 그려 준다는 뜻은 아닙니다. 예레미야서의 전개를 통해 바벨론의 역할이 구체화되지만 첫 환상의 문학적 기능은 ‘북쪽에서 터지는 재앙’이라는 위협을 먼저 들려주는 데 있습니다."]},{"title":"두 환상의 상호 해석","paragraphs":["살구나무 환상과 끓는 가마 환상을 서로 무관한 두 상징으로 분리하면 12절의 ‘말씀을 지켜 이루심’이 추상적인 위로로 변하기 쉽습니다. 첫 환상은 누가 말씀을 성취시키시는지를, 둘째 환상은 그 말씀의 심판이 어떤 역사적 위기로 나타날지를 보여 줍니다. 하나님이 자신의 말씀을 성취하신다는 확신은 심판을 가볍게 만드는 근거가 아니라 오히려 그 심각성을 더합니다."]},{"title":"성문과 공적 심판","paragraphs":["15절의 왕좌와 성문은 사적인 불안이 아니라 왕국의 공적 질서가 무너지는 장면을 구성합니다. 이어지는 16절은 그 정치적 위기를 언약 배반과 우상숭배의 맥락에서 해석합니다. 본문은 정치와 예배를 서로 무관한 영역으로 떼어 놓지 않지만, 동시에 후대의 임의적인 전쟁 해석에 예언적 확실성을 부여하지도 않습니다."]},{"title":"책 전체에서 반복되는 견고함과 고난","paragraphs":["18–19절의 보호 약속은 예레미야 15:20의 ‘견고한 놋 성벽’ 이미지와 공명합니다. 20장과 38장의 박해는 예레미야가 물리적으로 아무 상처도 입지 않는다는 독법을 거부하게 합니다. 1장의 말씀은 선지자의 생애를 낭만화하지 않고, 반대의 현실 속에서 말씀을 지키시는 하나님과 그 말씀을 전해야 하는 사람의 긴장을 함께 놓습니다."]},{"title":"본문비평의 범위","paragraphs":["예레미야서는 마소라 전승과 고대 그리스어 전승 사이에 책 전체의 길이와 배열에 관한 중요한 차이가 알려져 있습니다. 그러나 그 일반적 사실만으로 1:11–19의 개별 표현에 확인되지 않은 이문을 만들어서는 안 됩니다. 이 원고의 절별 해설은 실제 대조한 히브리어 본문에 근거하며, 독립적으로 확인하지 않은 고대 번역의 특정 독법은 결론의 근거로 사용하지 않았습니다."]}],"relatedResearch":[],"readerSources":[{"name":"Tyndale Open Study Notes","locator":"Tyndale Open Study Notes · Tyndale House Publishers · 예레미야 1:11–12, 1:13–14, 1:17–19 관련 주해 및 예레미야서 서론, 제공 자료 release 1","license":"CC BY-SA 4.0"}],"notes":["연구 참고자료\n* Open Scriptures Hebrew Bible (OSHB) · Open Scriptures Hebrew Bible Project · 예레미야 1:11–19, 기존 JudeBible 히브리어 본문 v2.2 · CC BY 4.0\n   * 원자료: https://github.com/openscriptures/morphhb\n   * 사용·변경 고지: 히브리어 어절과 본문 흐름을 대조해 한국어로 해설했습니다. 앱의 생성된 표시 데이터는 원전 자체의 새 판본으로 주장하지 않습니다.\n* Westminster Leningrad Codex (WLC) · OSHB의 기반 히브리어 본문 · 예레미야 1장 기반 본문 · Public Domain\n   * 기반 판본 정보: https://github.com/openscriptures/morphhb\n* Open Scriptures Hebrew Lexicon · Open Scriptures Hebrew Bible Project · 예레미야 1:11–12의 שקד 관련 명사·동사 표제어, 검증된 LexicalIndex 원천 자료 · CC BY 4.0\n   * 원자료: https://github.com/openscriptures/HebrewLexicon\n   * 변경·번역 고지: 원천의 영어 짧은 뜻을 확인하고 한국어로 문맥에 맞게 풀이했습니다. 원천 어휘 자료와 별도의 한국어 풀이 자료를 동일한 저작물로 취급하지 않습니다.\n* Tyndale Open Study Notes · Tyndale House Publishers · 예레미야 1:11–12, 1:13–14, 1:17–19 관련 주해 및 예레미야서 서론, 제공 자료 release 1.25 / Copyright © 2022 Tyndale House Publishers · CC BY-SA 4.0\n   * 원자료: http://www.tyndaleopenresources.com\n   * 저작권자 지정 고지: Adapted from Tyndale Open Study Notes. The original work by Tyndale House Publishers is available for free at http://www.tyndaleopenresources.com.\n   * 변경·번역 고지: 살구나무의 언어유희, 북쪽 침입의 지리, 선지자의 반대와 보호 이미지에 관한 설명을 참고해 한국어 본문 해설로 재구성·확장했습니다.\n* Project01 예레미야 Book Profile · Jude Lee OS Project01 · JER_Jeremiah_BOOK_PROFILE_Theological_Filter_v0.2, 문학·신학 필터 · 내부 연구자료(외부 이용허락 별도 확인 필요)\n   * 사용 고지: 심판과 회복의 긴장 및 예레미야 소명의 책 전체 기능을 점검하는 내부 연구 기준으로 참조했습니다.","연구 및 재서술 안내\n이 글은 예레미야 1:11–19의 히브리어 본문과 실제 열람한 주해·내부 연구 필터를 대조해 작성한 한국어 WORBS 주석입니다. 공통 성경 자료(OSHB·WLC·히브리어 어휘 자료), 개별 본문 주해(Tyndale), Project01 내부 연구자료를 구별했습니다. 참고한 내용을 한국어로 다시 설명하고 확장한 관계를 위에 밝혔으며 원자료의 긴 문장을 연속적으로 옮기지 않았습니다. 이 원고 전체의 독립 저작물 또는 파생 저작물 여부는 별도의 법적 검토 없이 확정하지 않습니다.","라이선스\nOSHB와 Open Scriptures Hebrew Lexicon의 확인된 이용 조건은 CC BY 4.0(https://creativecommons.org/licenses/by/4.0/)이며 기반 WLC 본문은 Public Domain으로 식별됩니다. Tyndale Open Study Notes의 확인된 이용 조건은 CC BY-SA 4.0(https://creativecommons.org/licenses/by-sa/4.0/)으로, 저작권자 표시·변경 고지·동일조건변경허락의 요건을 별도로 따라야 합니다. Project01 내부 필터의 외부 이용허락은 별도 확인 대상입니다. 성경전서 개역한글판의 연속 번역문은 인용하지 않았고 재배포 허락을 가정하지 않습니다. 원고 전체의 단일 라이선스는 별도 권리 검증 전에 정하지 않습니다."],"sourceNotice":"연구 참고자료\n* Open Scriptures Hebrew Bible (OSHB) · Open Scriptures Hebrew Bible Project · 예레미야 1:11–19, 기존 JudeBible 히브리어 본문 v2.2 · CC BY 4.0\n   * 원자료: https://github.com/openscriptures/morphhb\n   * 사용·변경 고지: 히브리어 어절과 본문 흐름을 대조해 한국어로 해설했습니다. 앱의 생성된 표시 데이터는 원전 자체의 새 판본으로 주장하지 않습니다.\n* Westminster Leningrad Codex (WLC) · OSHB의 기반 히브리어 본문 · 예레미야 1장 기반 본문 · Public Domain\n   * 기반 판본 정보: https://github.com/openscriptures/morphhb\n* Open Scriptures Hebrew Lexicon · Open Scriptures Hebrew Bible Project · 예레미야 1:11–12의 שקד 관련 명사·동사 표제어, 검증된 LexicalIndex 원천 자료 · CC BY 4.0\n   * 원자료: https://github.com/openscriptures/HebrewLexicon\n   * 변경·번역 고지: 원천의 영어 짧은 뜻을 확인하고 한국어로 문맥에 맞게 풀이했습니다. 원천 어휘 자료와 별도의 한국어 풀이 자료를 동일한 저작물로 취급하지 않습니다.\n* Tyndale Open Study Notes · Tyndale House Publishers · 예레미야 1:11–12, 1:13–14, 1:17–19 관련 주해 및 예레미야서 서론, 제공 자료 release 1.25 / Copyright © 2022 Tyndale House Publishers · CC BY-SA 4.0\n   * 원자료: http://www.tyndaleopenresources.com\n   * 저작권자 지정 고지: Adapted from Tyndale Open Study Notes. The original work by Tyndale House Publishers is available for free at http://www.tyndaleopenresources.com.\n   * 변경·번역 고지: 살구나무의 언어유희, 북쪽 침입의 지리, 선지자의 반대와 보호 이미지에 관한 설명을 참고해 한국어 본문 해설로 재구성·확장했습니다.\n* Project01 예레미야 Book Profile · Jude Lee OS Project01 · JER_Jeremiah_BOOK_PROFILE_Theological_Filter_v0.2, 문학·신학 필터 · 내부 연구자료(외부 이용허락 별도 확인 필요)\n   * 사용 고지: 심판과 회복의 긴장 및 예레미야 소명의 책 전체 기능을 점검하는 내부 연구 기준으로 참조했습니다.\n\n연구 및 재서술 안내\n이 글은 예레미야 1:11–19의 히브리어 본문과 실제 열람한 주해·내부 연구 필터를 대조해 작성한 한국어 WORBS 주석입니다. 공통 성경 자료(OSHB·WLC·히브리어 어휘 자료), 개별 본문 주해(Tyndale), Project01 내부 연구자료를 구별했습니다. 참고한 내용을 한국어로 다시 설명하고 확장한 관계를 위에 밝혔으며 원자료의 긴 문장을 연속적으로 옮기지 않았습니다. 이 원고 전체의 독립 저작물 또는 파생 저작물 여부는 별도의 법적 검토 없이 확정하지 않습니다.\n\n라이선스\nOSHB와 Open Scriptures Hebrew Lexicon의 확인된 이용 조건은 CC BY 4.0(https://creativecommons.org/licenses/by/4.0/)이며 기반 WLC 본문은 Public Domain으로 식별됩니다. Tyndale Open Study Notes의 확인된 이용 조건은 CC BY-SA 4.0(https://creativecommons.org/licenses/by-sa/4.0/)으로, 저작권자 표시·변경 고지·동일조건변경허락의 요건을 별도로 따라야 합니다. Project01 내부 필터의 외부 이용허락은 별도 확인 대상입니다. 성경전서 개역한글판의 연속 번역문은 인용하지 않았고 재배포 허락을 가정하지 않습니다. 원고 전체의 단일 라이선스는 별도 권리 검증 전에 정하지 않습니다."},{"schema":"JBC_PASSAGE_READER_COMMENTARY_v1","researchId":"JER_002_001_013_WORBS_READER_DRAFT_20261018","researchType":"WORBS","researchDepth":"CORE","sourcePath":"G:/내 드라이브/Jude_Lee_OS/01_PROJECTS/01_목회연구_WORBS_BICS/WORKING_COMMENTARY66_20261011/JER_002_001_013_WORBS_READER_DRAFT_20261018.md","sourceSha256":"d71546014e58fe13cf57e95bb84f66310db8ff02212788bc50c3cf6317e370c9","passage":{"book":"jer","chapter":2,"v1":1,"v2":13,"ref":"예레미야 2:1–13"},"projectionStatus":"INTERNAL_READER_PROJECTION","professionalStatus":"CANDIDATE_REVIEW_ONLY","qualityStatus":"CANDIDATE_RESEARCH_REVIEW_REQUIRED","externalRelease":"NOT_AUTHORIZED","generatedByProject":"01_목회연구_WORBS_BICS","professionalAuthorityOwner":"01_목회연구_WORBS_BICS","title":"기억된 사랑과 버려진 생수의 근원","overview":["예레미야의 소명과 두 환상(1장) 다음에 처음 길게 들려오는 말씀은 이스라엘의 과거를 기억하시는 하나님의 음성으로 시작합니다. 하나님은 광야에서 자신을 따르던 백성을 젊은 시절의 신부에 비유하시고, 그 백성을 자신의 거룩한 첫 열매로 부르십니다. 그러나 곧 질문의 방향이 바뀝니다. 하나님에게서 무슨 잘못을 발견했기에 조상들이 그분을 떠났습니까? 출애굽과 광야의 인도를 왜 기억하지 않습니까? 풍요로운 땅에 들어와서는 어째서 그 땅을 더럽혔습니까? 본문은 이 물음들을 통해 이스라엘의 배반이 단순한 종교 취향의 변화가 아니라, 생명을 주시는 하나님과 맺은 언약 관계의 파괴임을 드러냅니다."],"centralMessage":"이 단락의 중심 논지는 **하나님이 먼저 구원하시고 인도하시며 자기 백성으로 구별하셨으나, 백성은 그 은혜를 잊고 무익한 것을 좇아 생명의 근원과 스스로 단절되었다**는 것입니다. 마지막의 생수의 근원과 터진 웅덩이의 대조는 앞선 모든 고발을 하나의 선명한 이미지로 묶습니다. 하나님을 버린 것은 더 나은 공급원을 발견한 합리적 선택이 아니라, 흐르는 물을 떠나 물을 간직할 수도 없는 저장 구덩이를 선택한 역설적 행동입니다. 따라서 본문을 ‘첫사랑을 되찾으라’는 감상적인 권면으로만 읽거나 ‘우상을 섬기면 복을 잃는다’는 거래 공식으로 축소해서는 안 됩니다. 이 말씀은 기억, 예배, 지도력, 땅, 생명의 근원을 둘러싼 언약의 논쟁입니다.","literaryStructure":[{"v1":1,"v2":3,"title":"하나님이 기억하시는 광야의 관계"},{"v1":4,"v2":5,"title":"하나님에게서 무슨 불의를 발견했는가"},{"v1":6,"v2":7,"title":"잊힌 출애굽과 더럽혀진 선물의 땅"},{"v1":8,"v2":8,"title":"길을 가르쳐야 할 이들의 실패"},{"v1":9,"v2":11,"title":"열방을 증인으로 부르는 언약 논쟁"},{"v1":12,"v2":13,"title":"놀라는 하늘, 생수의 근원, 금이 간 웅덩이"}],"sections":[{"id":"jer2-1-3","v1":1,"v2":3,"title":"하나님이 기억하시는 광야의 관계","paragraphs":["1절은 여호와의 말씀이 예레미야에게 임했다는 전달 공식입니다. 2절에서 선지자는 예루살렘이 듣도록 외치라는 명령을 받습니다. ‘예루살렘의 귀에’ 전하라는 표현은 사적인 묵상이 아니라 도시와 공동체를 향한 공적 선포의 성격을 강조합니다. 발화의 주체는 선지자 자신이 아니라 그를 보내신 하나님입니다. 1장의 ‘입에 둔 말씀’이 2장에서는 언약 백성을 직접 부르는 말씀으로 구체화됩니다.","하나님은 젊은 시절의 **חֶסֶד**(헤세드)와 혼인 때의 사랑을 기억하신다고 말씀하십니다. 헤세드는 단순한 낭만적 감정보다 관계 안에서 드러나는 충성·인애·헌신의 뜻을 지닐 수 있습니다. 여기에 ‘신부의 사랑’과 ‘나를 따라 광야로 갔다’는 표현이 겹쳐, 출애굽 이후의 이스라엘을 신랑을 따르는 신부의 모습으로 그립니다. 본문이 기억하는 광야는 씨 뿌리지 못하는 땅, 곧 인간이 스스로 안정된 생존을 보장하기 어려운 공간입니다. 그러므로 뒤따름은 편리한 길의 선택이 아니라 인도하시는 분을 신뢰하는 관계를 드러냅니다.","그렇다고 이 회고를 광야 세대가 역사적으로 한 번도 불평하거나 불순종하지 않았다는 선언으로 읽어서는 안 됩니다. 출애굽기와 민수기는 광야에서의 반복된 원망과 배반도 기록합니다. 예레미야 2장은 그 복잡한 역사를 연대기적으로 다시 서술하기보다, 처음 언약 관계가 맺어진 때의 사랑과 헌신을 현재의 배반에 맞세우는 예언적 회고를 사용합니다. 호세아 2장의 광야·혼인 이미지와도 울림이 있지만, 두 책의 표현을 곧바로 동일한 사건 기록으로 합쳐서는 안 됩니다.","3절에서 이스라엘은 하나님께 속한 **קֹדֶשׁ**(코데시, 거룩하게 구별된 것)이며 그분의 수확 가운데 ‘첫 열매’로 묘사됩니다. 첫 열매는 농업에서 수확의 시작을 하나님께 드리는 특별한 몫을 떠올리게 합니다(출 23:19; 레 23:10). 여기서 핵심은 이스라엘이 세계에서 시간상 첫 민족이라는 뜻이 아니라, 하나님께 특별히 속한 백성이라는 관계적 지위입니다. 이스라엘을 삼키려는 자들이 책임을 지고 재앙을 맞는다는 말은 하나님이 자기 백성을 보호하셨던 관계의 한 면을 나타냅니다. 이 보호의 기억은 곧바로 이어지는 백성의 배반을 더욱 뼈아프게 만듭니다."]},{"id":"jer2-4-5","v1":4,"v2":5,"title":"하나님에게서 무슨 불의를 발견했는가","paragraphs":["4절은 ‘야곱의 집’과 ‘이스라엘 집의 모든 가족’을 함께 부르며 청중의 범위를 넓힙니다. 유다 말기의 예루살렘에서 선포되는 말씀이라 하더라도, 고발은 남유다만의 순간적 실수로 좁혀지지 않습니다. 조상들과 후손을 잇는 언약 공동체 전체의 기억과 책임을 소환합니다. ‘들으라’는 명령은 예언자가 단지 정보를 전달하는 사람이 아니라 하나님 앞에서 공동체를 증언의 자리로 부르는 사람임을 보여 줍니다.","5절의 질문은 놀랍게도 하나님 자신을 심문대에 올리는 듯한 형식을 취합니다. 조상들이 하나님 안에서 어떤 **עָוֶל**(아벨, 불의·그릇됨)을 발견했기에 그분에게서 멀어졌습니까? 질문은 실제로 하나님에게 잘못이 있었다고 인정하는 것이 아니라, 배반의 정당한 이유를 제시할 수 있는지 따져 묻는 수사적 도전입니다. 백성이 떠난 까닭을 하나님의 신실하지 못하심에서 찾을 수 없다는 것이 고발의 핵심입니다.","이어지는 히브리어에는 ‘헛된 것’을 좇았고 ‘헛되게 되었다’는 소리와 의미의 반복이 있습니다. **הֶבֶל**(헤벨, 헛됨·실체 없는 것)을 좇아 그들 자신도 헛되게 되었다는 표현은 우상숭배를 단순히 금지된 물건을 소유한 행위로만 보지 않습니다. 사람이 궁극적으로 의지하고 따라가는 대상이 그 사람의 삶과 정체성을 빚는다는 통찰이 담겨 있습니다. 하나님께 속한 첫 열매였던 백성이 무익한 것을 좇아 스스로 무익해졌다는 반전은 3절과 5절을 강하게 연결합니다. 이것은 개인의 자존감을 깎아내리는 일반 심리 명제가 아니라, 언약 관계를 저버린 공동체에 대한 예언적 판단입니다."]},{"id":"jer2-6-7","v1":6,"v2":7,"title":"잊힌 출애굽과 더럽혀진 선물의 땅","paragraphs":["6절에서 하나님은 백성이 ‘우리를 애굽 땅에서 이끌어 올리신 여호와가 어디 계시는가’라고 묻지 않았다고 책망하십니다. 여기서 ‘어디 계시는가’는 하나님이 지리적으로 사라졌다는 질문이 아닙니다. 자신들을 구원하시고 지금까지 인도하신 분을 찾고 인정하며 의지하는 언약적 기억의 표현입니다. 백성의 문제는 출애굽이라는 정보를 몰랐다는 데 그치지 않고, 그 구원의 기억이 현재의 예배와 선택을 규정하지 못하게 되었다는 데 있습니다.","광야는 황무지와 구덩이, 마른 땅과 짙은 어둠, 사람이 지나거나 거주하기 어려운 땅으로 여러 겹 묘사됩니다. 히브리어의 병렬 표현은 위험하고 생존이 불안정한 지형의 경험을 축적합니다. 이것을 광야 여정의 정확한 숙영지나 특정 협곡을 복원하는 지리 목록으로 취급해서는 안 됩니다. 본문은 지도의 세부 좌표보다 그곳에서 백성이 자기 힘만으로 살 수 없었고 하나님이 그들을 인도하셨다는 사실을 강조합니다.","7절에서 하나님은 그들을 **אֶרֶץ הַכַּרְמֶל**(비옥하고 열매 맺는 땅)로 데려오셨다고 말씀하십니다. 이 표현을 반드시 갈멜산이라는 한 지점으로 제한할 이유는 없습니다. 여기서는 광야와 대비되는 비옥한 땅의 성격이 중요합니다. 백성은 그 열매와 좋은 것을 누리도록 인도받았지만, 들어와서 하나님의 땅을 더럽히고 그분의 기업을 가증하게 만들었습니다. ‘내 땅’, ‘내 기업’이라는 소유 표현은 가나안이 백성의 무제한적 사유물이 아니라 하나님에게서 받은 선물이라는 신학적 관점을 드러냅니다. 은혜로 받은 공간이 그 은혜를 거스르는 행위의 무대가 되었다는 역설이 여기 있습니다."]},{"id":"jer2-8-8","v1":8,"v2":8,"title":"길을 가르쳐야 할 이들의 실패","paragraphs":["8절은 책임을 지도층으로 좁혀 비춥니다. 제사장들은 ‘여호와가 어디 계시는가’라고 묻지 않았고, 율법을 다루는 자들은 하나님을 알지 못했으며, 목자들은 반역했고, 선지자들은 바알의 이름으로 예언하며 유익하지 않은 것을 따랐습니다. 이 네 집단은 단순히 직업별 악인을 나열하는 목록이 아닙니다. 제의, 율법의 보존과 해석, 공동체 통치, 예언적 분별이라는 서로 다른 책임의 자리가 모두 흔들렸음을 보여 줍니다.","‘율법을 다루는 자들’의 실패는 율법 문서가 없었다는 주장과 다릅니다. 하나님의 말씀을 취급하는 직무가 하나님을 아는 관계와 분리될 수 있다는 고발입니다. ‘목자들’은 문맥상 양을 치는 목동만이 아니라 백성을 이끄는 통치·지도 역할을 가리키는 은유로 읽는 것이 자연스럽습니다. 바알의 이름으로 예언했다는 말은 예언자라는 직함 자체가 참된 말씀의 보증이 되지 못한다는 사실을 드러냅니다. 1장에서 왕·지도자·제사장·백성이 예레미야에게 저항할 것이라는 예고가 이 고발과 이어집니다.","특히 6절과 8절에서 되풀이되는 ‘여호와가 어디 계시는가’라는 부재의 질문은 백성과 지도자가 함께 하나님을 찾지 않는 상황을 드러냅니다. 백성의 망각은 지도층의 왜곡된 예배와 가르침에 의해 교정되기는커녕 더욱 굳어집니다. 예레미야서 후반에 나타날 거짓 평안과 거짓 예언의 문제가 이미 이곳에서 씨앗처럼 제시됩니다."]},{"id":"jer2-9-11","v1":9,"v2":11,"title":"열방을 증인으로 부르는 언약 논쟁","paragraphs":["9절의 ‘내가 너희와 다투겠다’에서 동사 **רִיב**(리브, 다투다·논쟁하다)는 예언서의 언약 소송을 이해하는 중요한 단서입니다. 하나님은 백성에게 막연한 분노를 쏟으시는 것이 아니라, 관계의 역사를 근거로 배반의 이유를 따져 물으십니다. 자손의 자손과도 다투겠다는 표현은 죄책이 아무 설명 없이 기계적으로 세습된다는 선언이라기보다, 이 배반이 한 세대에 그치지 않고 이어질 수 있음을 경고하는 긴 시간의 전망으로 읽어야 합니다. 본문 자체는 개별 후손의 책임을 심판하는 모든 법적 원리를 자세히 규정하지 않습니다.","10절은 서쪽의 깃딤 해안 지역과 동쪽의 게달을 향해 사람을 보내 살펴보라고 합니다. 깃딤은 고대 지중해, 특히 키프로스와 연관되는 명칭으로 이해되며, 게달은 아라비아계 유목 집단을 가리킵니다. 둘은 하나의 정확한 직선 경로를 지정하기보다 서쪽과 동쪽의 넓은 세계를 둘러보라는 수사적 대조를 이룹니다. ‘어느 민족에게 이런 일이 있었는가’라는 물음은 비교의 범위를 극대화합니다. 이 지리적 이름들을 특정한 현대 국경이나 모든 시대의 거주지를 확정하는 좌표로 사용할 수는 없습니다.","11절의 대조는 더욱 날카롭습니다. 신이 아닌 신들을 섬기는 민족들조차 자기 신을 쉽게 바꾸지 않는데, 하나님의 백성은 자기의 ‘영광’을 무익한 것으로 바꾸었습니다. 이 ‘영광’은 이스라엘의 자랑스러운 문화적 명성만을 가리키기보다, 그 백성의 참된 영광이신 하나님과의 관계를 포함하는 표현으로 읽을 수 있습니다. 우상들이 참된 신이 아니라는 신학적 판단과, 그 우상들을 붙드는 민족들조차 보이는 충성에 비해 이스라엘의 배반이 얼마나 터무니없는지를 묻는 비교가 함께 작동합니다. 이 구절을 다른 민족의 종교에 대한 현대적 조롱이나 집단적 적대의 근거로 바꾸어서는 안 됩니다."]},{"id":"jer2-12-13","v1":12,"v2":13,"title":"놀라는 하늘, 생수의 근원, 금이 간 웅덩이","paragraphs":["12절은 하늘을 향해 놀라고 떨며 심히 황폐해지라고 외칩니다. 예언적 시에서 하늘은 인간 공동체의 언약 배반을 지켜보는 우주적 증인으로 등장합니다. 신명기 32:1이 하늘과 땅을 불러 말씀을 듣게 하고, 이사야 1:2가 하늘과 땅을 증인으로 소환하는 것과 비교할 수 있습니다. 예레미야는 이 오래된 언약 언어를 통해 이스라엘의 배반이 작은 의례상의 실수가 아니라 창조 세계 앞에 드러날 만큼 심각한 관계 파괴임을 표현합니다. 하늘이 문자적으로 감정을 느낀다는 자연과학적 진술로 읽을 필요는 없습니다.","13절은 ‘두 가지 악’을 밝힙니다. 첫째, 백성이 **מְקוֹר מַיִם חַיִּים**(메코르 마임 하임, 살아 있는 물의 근원)이신 하나님을 버렸습니다. 둘째, 스스로 웅덩이를 팠는데 그것은 물을 담아 두지 못하는 깨진 웅덩이입니다. ‘살아 있는 물’은 고여 있는 물과 대비되는 흐르는 물, 솟아나는 샘물을 떠올리게 합니다. 건조한 기후에서 안정적인 물 공급은 생존과 정착의 중요한 조건이었습니다. 비가 올 때 물을 모으는 저수 웅덩이나 빗물 저장시설은 실제로 유익한 기술이지만, 균열이 생겨 물이 새면 그 기능을 잃습니다. 그러므로 이 비유는 모든 인공 저장시설을 악하다고 말하지 않습니다. **마르지 않는 공급원을 버리고 물을 보존할 수조차 없는 대체물을 스스로 만든 선택**이 문제입니다.","본문의 두 악은 단순한 동의어의 반복이 아닙니다. 하나님을 떠나는 소극적 배반과, 그 빈자리를 메우기 위해 무익한 의존 대상을 적극적으로 만들어 내는 행동이 결합됩니다. 5절의 ‘헛된 것을 좇아 헛되게 됨’과 11절의 ‘영광을 무익한 것으로 바꿈’이 이 마지막 이미지에서 완성됩니다. 생수는 하나님이 공급하시는 생명의 지속성을, 터진 웅덩이는 하나님을 대신하려는 종교적·정치적 의존의 무능을 상징합니다. 이어지는 14–19절에서 애굽과 앗수르의 길과 강물이 언급되는 것은 이 물의 이미지를 정치적 의존의 문제로도 확장해 읽게 합니다. 다만 13절의 웅덩이를 곧바로 특정 국가나 한 가지 제도에만 일대일로 대응시키는 것은 본문의 비유를 지나치게 좁힙니다."]}],"lexicalCards":[],"discoveries":[],"canonicalLinks":[],"theologicalSynthesis":[],"alternativeReadings":[{"title":"헤세드와 혼인 은유의 문법","paragraphs":["2절의 ‘젊은 시절의 헤세드’와 ‘혼인 때의 사랑’은 하나님이 기억하시는 관계를 묘사합니다. ‘내가 너를 기억한다’는 문맥에서 두 표현은 백성의 초기 헌신을 가리키는 것으로 읽히지만, 이 기억은 하나님이 먼저 백성을 구원하고 이끄셨다는 더 큰 이야기 속에 놓여 있습니다. 따라서 ‘처음에는 백성이 완전했고 나중에만 타락했다’는 도식은 광야 전승 전체와 어긋납니다. 예언적 회고는 현재의 배반을 비추기 위해 과거 관계의 한 측면을 전면에 놓습니다."]},{"title":"헤벨의 반복과 예배의 형성력","paragraphs":["5절의 ‘헛된 것’과 ‘헛되게 됨’은 같은 어근을 되풀이해 숭배 대상과 숭배자의 변화를 묶습니다. 전도서의 헤벨을 그대로 끌어와 이 구절을 삶 전체의 무의미 선언으로 해석하는 것은 문맥상 과도합니다. 예레미야에서 직접적인 표적은 하나님을 떠나 무익한 신들을 좇는 언약 배반입니다. 8절의 ‘유익하지 않은 것’과 11절의 ‘무익한 것’이 같은 논지를 이어갑니다."]},{"title":"광야와 비옥한 땅의 대비","paragraphs":["6–7절은 건조하고 위험한 공간에서의 인도와 풍요로운 공간에서의 오염을 병치합니다. 광야가 도덕적으로 더 거룩하고 정착 자체가 타락이라는 주장은 아닙니다. 하나님의 인도에 대한 의존을 기억하지 않는다면, 선물로 받은 풍요도 배반의 무대가 될 수 있다는 것이 본문의 역설입니다. ‘비옥한 땅’이라는 표현을 갈멜산의 한 지점으로 한정하지 않는 것도 이러한 문학적 대조에 부합합니다."]},{"title":"리브와 언약 소송의 범위","paragraphs":["9절의 רִיב는 논쟁·다툼의 어휘이며, 4–13절의 수사적 질문과 증인 소환은 언약 소송으로 읽을 근거를 줍니다. 그러나 본문을 현대 법정의 원고·검사·판사 역할에 완전히 맞춰 배치할 필요는 없습니다. 여기서 중요한 것은 하나님이 출애굽과 땅의 선물을 근거로 백성의 배반을 공적으로 드러내신다는 점입니다. 신명기 32장과 이사야 1장은 이러한 언약적 증언의 언어를 이해하는 데 도움을 줍니다."]},{"title":"깃딤과 게달의 역사적 지시","paragraphs":["두 이름은 서로 다른 지리적 세계를 호출합니다. 깃딤은 키프로스와 동지중해 세계에 연결되고, 게달은 아라비아계 집단과 연결됩니다. 시대에 따라 명칭의 적용 범위가 달라질 수 있으므로 특정 현대 지도를 한 번의 좌표로 고정해서는 안 됩니다. 본문의 목적은 고대 국제 교역로를 재구성하는 것이 아니라 이스라엘의 변절이 얼마나 이례적인지를 비교하는 것입니다."]},{"title":"샘과 웅덩이의 물질문화","paragraphs":["팔레스타인 산지와 건조 지역의 고대 정착지는 강수량의 계절성 때문에 샘과 빗물 저장시설을 모두 활용했습니다. 웅덩이는 바위를 파거나 내부에 방수 처리를 하여 물을 저장할 수 있지만, 금이 가면 물이 새어 생존에 필요한 공급을 유지하지 못합니다. 본문은 그 현실적인 취약성을 빌려 신학적 역설을 구성합니다. 시편 36:9의 ‘생명의 원천’과 연결해 볼 수 있고, 요한복음 4장의 생수 언어와 정경적으로 대화할 수 있으나, 예레미야 2장의 일차 문맥은 우선 유다와 이스라엘의 언약 배반입니다. 후대 본문을 먼저 가져와 예레미야의 역사적 고발을 지워서는 안 됩니다."]},{"title":"본문비평의 경계","paragraphs":["예레미야서에는 마소라 히브리어 전승과 고대 그리스어 전승의 분량·배열 차이가 알려져 있습니다. 그러나 이 일반적인 차이만으로 2:1–13의 특정 절에 확인하지 않은 이문이나 원문 복원을 제시할 수는 없습니다. 이 해설의 원어 관찰은 확인한 히브리어 본문에 한정하며, 독립 대조하지 않은 그리스어의 개별 독법을 논증의 근거로 삼지 않습니다."]}],"relatedResearch":[],"readerSources":[{"name":"Tyndale Open Study Notes","locator":"Tyndale Open Study Notes · Tyndale House Publishers · 예레미야 2:1–13 관련 주해, StudyNotes","license":"CC BY-SA 4.0"}],"notes":["연구 참고자료\n* Open Scriptures Hebrew Bible (OSHB) · Open Scriptures Hebrew Bible Project · 예레미야 2:1–13, JudeBible 로컬 히브리어 본문 v2.2 · CC BY 4.0\n   * 원자료: https://github.com/openscriptures/morphhb\n   * 사용·변경 고지: 히브리어 어절과 문학적 반복을 대조하여 한국어로 해설했습니다. 앱 표시용으로 생성된 데이터와 원천 판본을 구별합니다.\n* Westminster Leningrad Codex (WLC) · OSHB의 기반 히브리어 본문 · 예레미야 2장 기반 본문 · Public Domain\n   * 기반 판본 정보: https://github.com/openscriptures/morphhb\n* Tyndale Open Study Notes · Tyndale House Publishers · 예레미야 2:1–13 관련 주해, StudyNotes.xml release 1.25 / Copyright © 2022 Tyndale House Publishers · CC BY-SA 4.0\n   * 원자료: http://www.tyndaleopenresources.com\n   * 저작권자 지정 고지: Adapted from Tyndale Open Study Notes. The original work by Tyndale House Publishers is available for free at http://www.tyndaleopenresources.com.\n   * 변경 고지: 관련 주해의 배경 설명과 상호본문적 단서를 확인한 뒤 한국어 문학·신학 해설로 선택·재구성했습니다. 원문의 문장과 번역을 그대로 옮긴 것이 아닙니다.\n* 예레미야 Book Profile · Jude Lee OS Project01 · JER_Jeremiah_BOOK_PROFILE_Theological_Filter_v0.2 · 내부 연구 방향 자료, 외부 이용허락 별도 확인 필요\n   * 사용 고지: 예언서의 언약 소송, 심판과 새 언약의 긴장, 거짓 평안 비판이라는 책 전체의 독법을 점검하는 내부 해석 기준으로 사용했습니다.","연구 및 재서술 안내\n이 원고는 예레미야 2:1–13의 히브리어 본문을 중심으로 작성한 WORBS 기반 한국어 주석입니다. 실제 대조한 히브리어 원문과 Tyndale Open Study Notes의 관련 항목을 참고하여 역사·문학·신학적 설명을 재구성했습니다. 개역한글 번역문을 연속 인용하지 않았으며, 사용한 자료의 번역·변형 관계를 밝히되 원고 전체가 독립 저작물인지 파생 저작물인지는 단정하지 않습니다.","라이선스\nOSHB는 CC BY 4.0(https://creativecommons.org/licenses/by/4.0/) 조건에 따라, 그 기반 WLC 본문은 Public Domain으로 구분합니다. Tyndale Open Study Notes는 CC BY-SA 4.0(https://creativecommons.org/licenses/by-sa/4.0/) 조건과 원저작자 표시 및 변경 고지의 적용을 받습니다. Project01 내부 연구 자료에는 별도의 공개 이용허락을 부여하지 않습니다. 원고 전체에 적용될 라이선스는 자료별 권리 관계를 추가 검토하기 전에는 확정하지 않습니다."],"sourceNotice":"연구 참고자료\n* Open Scriptures Hebrew Bible (OSHB) · Open Scriptures Hebrew Bible Project · 예레미야 2:1–13, JudeBible 로컬 히브리어 본문 v2.2 · CC BY 4.0\n   * 원자료: https://github.com/openscriptures/morphhb\n   * 사용·변경 고지: 히브리어 어절과 문학적 반복을 대조하여 한국어로 해설했습니다. 앱 표시용으로 생성된 데이터와 원천 판본을 구별합니다.\n* Westminster Leningrad Codex (WLC) · OSHB의 기반 히브리어 본문 · 예레미야 2장 기반 본문 · Public Domain\n   * 기반 판본 정보: https://github.com/openscriptures/morphhb\n* Tyndale Open Study Notes · Tyndale House Publishers · 예레미야 2:1–13 관련 주해, StudyNotes.xml release 1.25 / Copyright © 2022 Tyndale House Publishers · CC BY-SA 4.0\n   * 원자료: http://www.tyndaleopenresources.com\n   * 저작권자 지정 고지: Adapted from Tyndale Open Study Notes. The original work by Tyndale House Publishers is available for free at http://www.tyndaleopenresources.com.\n   * 변경 고지: 관련 주해의 배경 설명과 상호본문적 단서를 확인한 뒤 한국어 문학·신학 해설로 선택·재구성했습니다. 원문의 문장과 번역을 그대로 옮긴 것이 아닙니다.\n* 예레미야 Book Profile · Jude Lee OS Project01 · JER_Jeremiah_BOOK_PROFILE_Theological_Filter_v0.2 · 내부 연구 방향 자료, 외부 이용허락 별도 확인 필요\n   * 사용 고지: 예언서의 언약 소송, 심판과 새 언약의 긴장, 거짓 평안 비판이라는 책 전체의 독법을 점검하는 내부 해석 기준으로 사용했습니다.\n\n연구 및 재서술 안내\n이 원고는 예레미야 2:1–13의 히브리어 본문을 중심으로 작성한 WORBS 기반 한국어 주석입니다. 실제 대조한 히브리어 원문과 Tyndale Open Study Notes의 관련 항목을 참고하여 역사·문학·신학적 설명을 재구성했습니다. 개역한글 번역문을 연속 인용하지 않았으며, 사용한 자료의 번역·변형 관계를 밝히되 원고 전체가 독립 저작물인지 파생 저작물인지는 단정하지 않습니다.\n\n라이선스\nOSHB는 CC BY 4.0(https://creativecommons.org/licenses/by/4.0/) 조건에 따라, 그 기반 WLC 본문은 Public Domain으로 구분합니다. Tyndale Open Study Notes는 CC BY-SA 4.0(https://creativecommons.org/licenses/by-sa/4.0/) 조건과 원저작자 표시 및 변경 고지의 적용을 받습니다. Project01 내부 연구 자료에는 별도의 공개 이용허락을 부여하지 않습니다. 원고 전체에 적용될 라이선스는 자료별 권리 관계를 추가 검토하기 전에는 확정하지 않습니다."},{"schema":"JBC_PASSAGE_READER_COMMENTARY_v1","researchId":"JER_002_014_022_WORBS_READER_DRAFT_20261018","researchType":"WORBS","researchDepth":"CORE","sourcePath":"G:/내 드라이브/Jude_Lee_OS/01_PROJECTS/01_목회연구_WORBS_BICS/WORKING_COMMENTARY66_20261011/JER_002_014_022_WORBS_READER_DRAFT_20261018.md","sourceSha256":"53a517c97d6c128880a2211b56dc0239862d537ff068ea7797261e9a33703f8a","passage":{"book":"jer","chapter":2,"v1":14,"v2":22,"ref":"예레미야 2:14–22"},"projectionStatus":"INTERNAL_READER_PROJECTION","professionalStatus":"CANDIDATE_REVIEW_ONLY","qualityStatus":"CANDIDATE_RESEARCH_REVIEW_REQUIRED","externalRelease":"NOT_AUTHORIZED","generatedByProject":"01_목회연구_WORBS_BICS","professionalAuthorityOwner":"01_목회연구_WORBS_BICS","title":"구원의 길을 떠나 다시 속박을 부르는 선택","overview":["앞 단락에서 하나님은 자기 백성이 생수의 근원을 버리고 물을 담지 못하는 웅덩이를 팠다고 고발하셨습니다(2:13). 이어지는 14–22절은 그 비유를 이스라엘과 유다의 역사적 상처, 강대국을 향한 의존, 예배의 배반으로 펼쳐 보입니다. 자유롭게 구원받은 백성이 어째서 약탈의 대상이 되었습니까? 애굽과 앗수르로 향하는 길에서 무엇을 얻으려 합니까? 하나님이 좋은 포도나무로 심으신 백성이 어떻게 낯선 포도나무처럼 되었습니까? 이 물음들은 하나님의 백성에게 닥친 위기를 단순한 외교 실패나 군사력 부족의 결과로만 설명하지 않습니다."],"centralMessage":"이 단락의 중심 논지는 **하나님이 인도하시고 자유롭게 하신 백성이 그분을 떠나 강대국과 다른 신들에게 안전을 구했지만, 그 선택 자체가 굴욕과 심판의 길이 되었다**는 것입니다. 14–19절은 정치적·역사적 결과를 묻고, 20–22절은 오래된 배반을 멍에와 포도나무와 씻을 수 없는 얼룩의 이미지로 폭로합니다. 그렇다고 이 본문을 모든 국가적 재난이 피해자의 종교적 잘못 때문에 발생한다는 보편 법칙으로 바꾸어서는 안 됩니다. 여기서는 하나님이 예레미야를 통해 특정 언약 공동체의 역사와 책임을 해석하시는 예언적 발화가 중심입니다.","literaryStructure":[{"v1":14,"v2":16,"title":"종이 아닌 백성이 약탈당하는 까닭"},{"v1":17,"v2":18,"title":"길에서 인도하신 분을 버리고 다른 길을 찾다"},{"v1":19,"v2":19,"title":"악행이 스스로를 책망하는 역설"},{"v1":20,"v2":20,"title":"꺾인 멍에와 높은 산 아래의 배반"},{"v1":21,"v2":21,"title":"좋은 포도나무가 낯선 가지가 되다"},{"v1":22,"v2":22,"title":"씻어도 지워지지 않는 죄의 얼룩"}],"sections":[{"id":"jer2-14-16","v1":14,"v2":16,"title":"종이 아닌 백성이 약탈당하는 까닭","paragraphs":["14절은 ‘이스라엘이 종인가, 집에서 태어난 노예인가’라는 두 질문으로 시작합니다. 두 질문은 단순한 신분 조사라기보다, 구원받아 하나님께 속한 백성이 어째서 다른 세력의 노략물이 되었는지 묻는 탄식과 고발입니다. 출애굽은 노예 상태에서의 해방을 이스라엘 정체성의 기초로 삼았습니다. 그런데 지금 백성은 마치 주인 없는 재산처럼 강대국의 공격에 노출되어 있습니다. 여기서 ‘이스라엘’은 북왕국만을 가리킨다고 단정하기 어렵습니다. 앞선 2:4에서 야곱의 집과 이스라엘의 모든 가족이 소환되었고, 예레미야의 직접적인 역사 무대는 유다와 예루살렘이기 때문입니다. 북왕국의 멸망 경험과 남유다의 위기가 서로 겹쳐 들리는 예언적 호칭으로 주의 깊게 읽어야 합니다.","15절의 젊은 사자들은 그를 향해 으르렁거리며 땅을 황폐하게 만들고 성읍을 사람이 살지 못할 곳으로 바꿉니다. 사자는 고대 근동에서 왕권과 군사력, 맹렬한 공격을 떠올리게 하는 강력한 이미지입니다. 앗수르 제국의 침략과 북왕국의 몰락을 역사적 배경으로 생각할 수 있지만, 본문이 모든 사자를 한 왕이나 한 번의 전쟁에만 대응시킨다고 볼 근거는 충분하지 않습니다. 예언적 시는 여러 차례의 상처를 압축하여, 하나님의 백성이 어떻게 먹잇감처럼 되었는지 보여 줍니다. 파괴된 성읍의 이미지도 한 도시의 정확한 유적 위치를 지정하는 지리 보고서가 아닙니다.","16절은 애굽의 **놉**과 **다바네스** 사람들을 언급합니다. 놉은 일반적으로 고대 멤피스와 연결되고, 다바네스는 동부 나일 삼각주의 타흐판헤스와 연결되는 지명입니다. 두 이름은 애굽의 실제 정치·지리적 세계를 불러오면서, 유다가 의지하려 했던 남쪽의 강대국이 오히려 수치와 피해의 원인이 될 수 있음을 암시합니다. 머리의 정수리를 상하게 한다는 표현은 굴욕과 공격을 드러내는 강렬한 이미지입니다. 히브리어 동사의 정확한 뉘앙스와 번역에는 해석상의 여지가 있으므로, 특정한 머리 깎기 의식이나 하나의 전투 장면을 사실로 단정하지 않는 편이 안전합니다. 지명이 등장한다고 해서 본문이 특정 시점의 군대 이동 경로 전체를 확정해 주는 것은 아닙니다."]},{"id":"jer2-17-18","v1":17,"v2":18,"title":"길에서 인도하신 분을 버리고 다른 길을 찾다","paragraphs":["17절은 앞선 질문들에 대한 해석을 제공합니다. ‘너를 길로 인도하시던 네 하나님 여호와를 버린 것’이 지금의 상황을 스스로 불러온 원인이라는 것입니다. 여기서 **דֶּרֶךְ**(데레크, 길)는 실제 이동의 길을 떠올리게 하면서 동시에 삶의 방향과 충성의 선택을 나타냅니다. 출애굽과 광야에서 하나님이 앞서 인도하셨다는 2:6의 기억이 다시 호출됩니다. 2:13에서 생명의 근원을 버린 행동이 2:17에서는 길의 인도자를 버린 행동으로 표현되는 셈입니다. 물과 길이라는 두 이미지는 모두 사람이 자기 생존과 미래를 누구에게 맡기는가라는 질문으로 모입니다.","18절의 질문은 구체적입니다. 애굽으로 가는 길에서 **시홀**의 물을 마시려는 까닭이 무엇이며, 앗수르로 가는 길에서 ‘그 강’의 물을 마시려는 까닭이 무엇입니까? 시홀은 애굽의 나일 수계와 관련된 이름으로 이해되지만, 그 표현이 언제나 현대 지도의 단일 수로 하나를 지시한다고 단정할 수는 없습니다. ‘그 강’은 성경의 여러 문맥에서 유프라테스를 가리키는 관용적 명칭입니다. 이 두 물줄기는 지리적으로 서로 다른 강대국의 세계를 대표합니다. 그러나 이 절의 목적은 고대 수문 지도를 제공하는 데 있지 않습니다. 물을 마신다는 행위는 생존과 의존을 암시하며, 정치적 보호를 얻기 위해 외부 세력에 기대는 선택을 신학적으로 묻습니다.","역사적으로 유다와 이스라엘의 왕들은 애굽과 앗수르 사이에서 조공, 외교, 반란, 동맹의 압력을 경험했습니다(왕하 17–19장; 23장). 그러나 예레미야 2:18만으로 특정 조약의 날짜, 왕의 이름, 사절단의 이동 경로를 복원할 수는 없습니다. 더욱이 본문이 비판하는 것은 모든 외교 활동 자체가 언제나 죄라는 일반 원칙이 아니라, 하나님을 버리고 다른 힘을 최종적인 안전의 근원으로 삼는 언약적 불신실입니다. 2:13의 터진 웅덩이는 이제 애굽과 앗수르라는 거대한 정치적 의존의 세계와 연결되어 그 무익함을 드러냅니다."]},{"id":"jer2-19-19","v1":19,"v2":19,"title":"악행이 스스로를 책망하는 역설","paragraphs":["19절은 백성의 악과 배역이 그들 자신을 징계하고 책망할 것이라고 선언합니다. 여기서 심판은 단지 외부에서 임의로 가해지는 형벌로만 표현되지 않습니다. 하나님을 떠난 선택이 자신의 파괴적 결과를 낳아, 그 결과가 다시 선택의 실상을 드러내는 구조입니다. 악이 스스로를 징계한다는 표현은 모든 고난을 즉시 개인의 특정 죄와 연결하라는 뜻이 아니라, 이 예언이 고발하는 언약 배반의 내적 모순을 밝힙니다.","이어지는 ‘알고 보라’는 명령은 지적 정보의 습득보다 역사적 경험을 올바르게 해석하라는 요청입니다. 하나님을 버리고 그분을 경외하지 않는 일이 얼마나 악하고 쓰라린지 알아야 한다는 것입니다. **경외**는 단순히 벌이 무서워 움츠러드는 감정이 아닙니다. 하나님이 누구신지 인정하고 그분의 말씀 앞에서 삶의 방향을 정하는 언약적 태도를 포함합니다. 2:5의 ‘무슨 불의를 발견했기에 떠났는가’라는 질문이 여기서는 떠난 선택의 실제 열매를 직시하라는 요청으로 돌아옵니다.","19절의 결론은 애굽과 앗수르의 강물이 하나님을 대신할 수 없다는 앞선 질문을 신학적으로 정리합니다. 외교와 권력의 역사를 읽는 예언자의 관점은 정치적 사건의 모든 복잡성을 지우지 않으면서도, 하나님을 떠난 공동체의 불신실이 위기의 중심에 있음을 선언합니다. 예레미야서는 이후에도 거짓 평안과 잘못된 의존을 반복하여 고발하지만, 여기서 이미 그 논리의 뼈대가 드러납니다."]},{"id":"jer2-20-20","v1":20,"v2":20,"title":"꺾인 멍에와 높은 산 아래의 배반","paragraphs":["20절에서 발화는 오래전부터의 관계로 돌아갑니다. 하나님이 멍에를 부수고 결박을 끊으셨다는 진술은 해방의 기억을 불러옵니다. 그런데 백성의 응답은 자유를 하나님과의 신실한 관계 안에서 살아가는 대신, 그분에게 복종하지 않겠다는 선언으로 나타납니다. 히브리어 본문에는 ‘섬기지 않겠다’와 ‘범하지 않겠다’로 읽힐 수 있는 자음 전승과 읽기 전승의 차이가 있어, 문장의 세부 번역은 판본·번역에 따라 달라질 수 있습니다. 어느 읽기를 따르든 뒤이어 묘사되는 높은 산과 푸른 나무 아래의 우상숭배가 이 문맥의 중심 고발이라는 점은 분명합니다. 한 읽기만을 유일한 원문으로 확정해 나머지를 숨길 이유는 없습니다.","높은 산과 무성한 나무 아래라는 표현은 고대 이스라엘의 제의적 장소들을 연상시킵니다(신 12:2; 왕하 17:10). 그러나 모든 높은 산과 나무가 곧 우상숭배 장소였다는 뜻은 아닙니다. 본문은 그러한 장소에서 하나님이 아닌 다른 신을 향해 몸을 굽힌 예배의 배반을 문제 삼습니다. 음행의 은유 역시 한 개인의 성적 행위를 선정적으로 묘사하기보다, 혼인 관계에 비유된 언약의 불충실을 드러내는 예언적 언어입니다. 이 은유를 현대의 학대 피해자에게 책임을 전가하거나 폭력을 정당화하는 근거로 사용해서는 안 됩니다.","20절의 멍에와 결박은 앞선 14절의 종·노예 질문과 맞물립니다. 하나님은 속박에서 구원하셨지만, 백성은 하나님에게서 자유로워지겠다고 주장하다 다른 의존과 굴욕의 길로 들어섭니다. 자유를 주신 분을 거부하는 일이 오히려 새로운 속박을 낳는다는 것이 이 단락의 역설입니다."]},{"id":"jer2-21-21","v1":21,"v2":21,"title":"좋은 포도나무가 낯선 가지가 되다","paragraphs":["21절에서 하나님은 백성을 귀한 포도나무, 곧 순전하고 좋은 씨로 심으셨다고 말씀하십니다. **שֹׂרֵק**(소레크)는 좋은 품종의 포도나무를 가리키는 표현으로 이해됩니다. ‘내가 심었다’는 선언은 백성이 우연히 땅에 자리 잡은 것이 아니라 하나님이 선택하고 돌보셨다는 관계의 기억을 담습니다. 2:7에서 하나님이 풍요로운 땅으로 데려오셨다는 진술과 연결하면, 좋은 땅과 좋은 포도나무라는 두 선물의 이미지가 겹칩니다.","그런데 하나님은 ‘어찌하여 내게 낯선 포도나무의 가지로 변했는가’라고 물으십니다. 식물의 품종이 생물학적으로 갑자기 바뀌었다는 관찰이 아니라, 하나님이 의도하신 언약적 열매와 백성이 실제로 드러낸 삶 사이의 단절을 표현하는 은유입니다. 포도나무의 변화는 2:5의 ‘헛된 것을 좇아 헛되게 됨’과 같은 변질의 논리를 다른 이미지로 말합니다. 이사야 5:1–7의 포도원 노래와도 정경적 대화가 가능하지만, 이사야가 열매와 공의의 문제를 두드러지게 제시한다면 예레미야 2:21은 심으신 분에 대한 배반과 변질의 충격에 집중합니다. 두 본문의 비유를 서로 구별하면서 읽어야 합니다."]},{"id":"jer2-22-22","v1":22,"v2":22,"title":"씻어도 지워지지 않는 죄의 얼룩","paragraphs":["22절은 다시 비유를 바꿉니다. 백성이 강한 세정 재료로 몸을 씻고 비누 같은 물질을 많이 사용해도, 그 죄악은 하나님 앞에 얼룩으로 남아 있다는 것입니다. 히브리어 **נֶתֶר**(네테르)는 알칼리성 세정 재료를, **בֹּרִית**(보리트)는 씻는 데 사용하는 잿물이나 세정 물질을 가리키는 말로 이해됩니다. 두 재료의 정확한 화학적 조성을 현대 상품의 성분표처럼 단정할 수는 없지만, 고대 사람들이 강한 세정력을 기대한 물질들이라는 점은 비유를 이해하는 데 충분합니다.","중요한 것은 백성이 세정 방법을 충분히 알지 못했다는 뜻이 아니라, 그들이 아무리 외적 방법을 동원해도 하나님 앞에 드러난 배반의 책임을 스스로 지워 버릴 수 없다는 점입니다. 이 이미지는 제의적 정결 행위 자체를 무조건 무가치하게 만드는 말도 아닙니다. 언약 배반의 실체를 외적 처리만으로 감출 수 없다는 선언입니다. 2:23 이하에서 백성이 ‘나는 더럽혀지지 않았다’고 부인하는 장면이 이어지므로, 22절은 그 자기변명의 길을 미리 차단합니다.","그렇다고 ‘씻어도 지워지지 않는다’를 하나님이 결코 용서하지 않으신다는 최종 판결로 확대해서는 안 됩니다. 예레미야서는 죄를 철저히 드러내면서도 후반부에 새 언약과 죄 사함의 약속을 선포합니다(31:31–34). 이 절이 부정하는 것은 인간이 스스로 마련한 표면적 세정으로 죄를 없던 일로 만들 수 있다는 생각입니다. 심판의 진실성을 보존해야 후대의 회복 약속도 값싼 면죄부로 변하지 않습니다."]}],"lexicalCards":[],"discoveries":[],"canonicalLinks":[],"theologicalSynthesis":[],"alternativeReadings":[{"title":"‘이스라엘’이라는 이름의 역사적 층위","paragraphs":["14–16절의 약탈과 사자 이미지는 북왕국의 멸망을 떠올리게 하지만, 예레미야의 발화는 남유다를 향한 경고의 맥락에서도 읽힙니다. 한 문단의 모든 동사를 단일 연도와 하나의 전쟁으로 환원하면 예언적 시가 역사적 상처를 중첩하는 방식을 놓치게 됩니다. 확실한 것은 본문이 해방받은 백성의 굴욕이라는 모순을 고발한다는 점이며, 개별 침공의 연대 배정에는 신중함이 필요합니다."]},{"title":"놉·다바네스와 시홀·그 강","paragraphs":["놉은 고대 멤피스, 다바네스는 동부 나일 삼각주 지역과 연결됩니다. 시홀은 애굽의 나일 수계, ‘그 강’은 통상 유프라테스를 가리키는 표현입니다. 16절의 도시는 정치·군사적 위협을, 18절의 강물은 생존과 의존의 대상을 암시합니다. 이 네 지시어가 특정 사절단의 이동 노선이나 강가의 정확한 접촉 지점을 기록한다고 보기는 어렵습니다. 고대 수계의 명칭과 도시의 범위를 확인할 때에도 본문의 비유적 기능과 실제 지리적 식별을 구별해야 합니다."]},{"title":"20절의 읽기 전승","paragraphs":["로컬 히브리어 본문에는 20절의 선언과 관련된 케티브·케레 표지가 나타납니다. ‘섬기지 않겠다’와 ‘범하지 않겠다’는 번역상의 차이는 문장의 세부 주체와 반항의 어조를 논의할 때 중요할 수 있습니다. 다만 여기서는 독립적인 고대 역본 대조를 마치지 않았으므로 한 독법의 역사적 우위를 확정하지 않습니다. 본문의 명백한 후반부, 곧 다른 제의 장소를 좇는 행동이 앞선 해방의 기억과 충돌한다는 사실을 해석의 중심에 둡니다."]},{"title":"포도나무의 상호본문성","paragraphs":["시편 80:8–16은 애굽에서 옮겨 심은 포도나무를, 이사야 5:1–7은 돌봄에도 좋은 열매를 맺지 못한 포도원을 그립니다. 예레미야 2:21은 그 공통된 식물 이미지 안에서 ‘심은 분’과 ‘변질된 나무’의 관계를 부각합니다. 이 비유들을 서로 연결할 수는 있지만, 각 본문이 고발하는 대상과 강조점이 같다고 전제해서는 안 됩니다."]},{"title":"세정 재료와 신학적 책임","paragraphs":["네테르와 보리트는 고대 세정 기술의 언어를 빌려 인간의 자기정당화가 실패함을 보여 줍니다. 세척의 이미지를 곧바로 특정한 정결 의식의 폐지 선언으로 만들면 본문을 넘어섭니다. 본문은 씻는 행위 자체가 아니라 하나님 앞에 남은 죄의 책임을 문제 삼습니다. 31장의 용서 약속과 함께 읽을 때에는 죄의 현실을 지우지 않는 회복이라는 예레미야서 전체의 긴장을 유지해야 합니다."]},{"title":"본문비평과 역사 확정의 한계","paragraphs":["예레미야서의 히브리어와 고대 그리스어 전승은 책 전체의 길이와 배열에서 중요한 차이를 보입니다. 그러나 그러한 일반적 사실만으로 2:14–22의 모든 단어에 확인되지 않은 이문을 덧붙일 수는 없습니다. 특히 20절은 실제 확인한 히브리어 본문에 표시된 읽기 전승의 차이만을 설명했으며, 확인하지 않은 역본의 특정 번역을 증거처럼 제시하지 않았습니다."]}],"relatedResearch":[],"readerSources":[{"name":"Tyndale Open Study Notes","locator":"Tyndale Open Study Notes · Tyndale House Publishers · 예레미야 2:14–22 관련 주해, StudyNotes","license":"CC BY-SA 4.0"}],"notes":["연구 참고자료\n* Open Scriptures Hebrew Bible (OSHB) · Open Scriptures Hebrew Bible Project · 예레미야 2:14–22, JudeBible 로컬 히브리어 본문 v2.2 · CC BY 4.0\n   * 원자료: https://github.com/openscriptures/morphhb\n   * 사용·변경 고지: 히브리어 어절과 20절의 읽기 전승 표지를 확인하고 한국어로 해설했습니다. 앱 표시용 생성 데이터와 원천 판본을 구별합니다.\n* Westminster Leningrad Codex (WLC) · OSHB의 기반 히브리어 본문 · 예레미야 2장 기반 본문 · Public Domain\n   * 기반 판본 정보: https://github.com/openscriptures/morphhb\n* Tyndale Open Study Notes · Tyndale House Publishers · 예레미야 2:14–22 관련 주해, StudyNotes.xml release 1.25 / Copyright © 2022 Tyndale House Publishers · CC BY-SA 4.0\n   * 원자료: http://www.tyndaleopenresources.com\n   * 저작권자 지정 고지: Adapted from Tyndale Open Study Notes. The original work by Tyndale House Publishers is available for free at http://www.tyndaleopenresources.com.\n   * 변경 고지: 해당 절의 역사적 지명과 강대국 관계에 관한 주해를 확인하고, 히브리어 본문을 중심으로 한국어 문학·신학 해설을 새로 구성했습니다. 원문을 그대로 번역하거나 전재하지 않았습니다.\n* 예레미야 Book Profile · Jude Lee OS Project01 · JER_Jeremiah_BOOK_PROFILE_Theological_Filter_v0.2 · 내부 연구 방향 자료, 외부 이용허락 별도 확인 필요\n   * 사용 고지: 언약 배반과 심판, 거짓 안전과 회복의 긴장에 관한 예레미야서 전체의 해석 경계를 점검했습니다.","연구 및 재서술 안내\n이 원고는 예레미야 2:14–22의 히브리어 본문을 중심으로 작성한 WORBS 기반 한국어 주석입니다. 실제 확인한 원문과 Tyndale Open Study Notes의 관련 항목을 참고하여 지리·역사·문학·신학 설명을 선택하고 재서술했습니다. 개역한글 번역문의 연속 인용은 사용하지 않았습니다. 원고의 독립 저작물·파생 저작물 여부는 단정하지 않습니다.","라이선스\nOSHB는 CC BY 4.0(https://creativecommons.org/licenses/by/4.0/) 조건을 따르며, 기반 WLC 본문은 Public Domain으로 구별합니다. Tyndale Open Study Notes는 CC BY-SA 4.0(https://creativecommons.org/licenses/by-sa/4.0/) 조건에 따른 원저작자 표시와 변경 고지가 필요합니다. Project01 내부 연구 자료의 공개 이용 조건은 별도 확인 대상입니다. 원고 전체의 라이선스는 자료별 권리 검토가 끝나기 전에는 확정하지 않습니다."],"sourceNotice":"연구 참고자료\n* Open Scriptures Hebrew Bible (OSHB) · Open Scriptures Hebrew Bible Project · 예레미야 2:14–22, JudeBible 로컬 히브리어 본문 v2.2 · CC BY 4.0\n   * 원자료: https://github.com/openscriptures/morphhb\n   * 사용·변경 고지: 히브리어 어절과 20절의 읽기 전승 표지를 확인하고 한국어로 해설했습니다. 앱 표시용 생성 데이터와 원천 판본을 구별합니다.\n* Westminster Leningrad Codex (WLC) · OSHB의 기반 히브리어 본문 · 예레미야 2장 기반 본문 · Public Domain\n   * 기반 판본 정보: https://github.com/openscriptures/morphhb\n* Tyndale Open Study Notes · Tyndale House Publishers · 예레미야 2:14–22 관련 주해, StudyNotes.xml release 1.25 / Copyright © 2022 Tyndale House Publishers · CC BY-SA 4.0\n   * 원자료: http://www.tyndaleopenresources.com\n   * 저작권자 지정 고지: Adapted from Tyndale Open Study Notes. The original work by Tyndale House Publishers is available for free at http://www.tyndaleopenresources.com.\n   * 변경 고지: 해당 절의 역사적 지명과 강대국 관계에 관한 주해를 확인하고, 히브리어 본문을 중심으로 한국어 문학·신학 해설을 새로 구성했습니다. 원문을 그대로 번역하거나 전재하지 않았습니다.\n* 예레미야 Book Profile · Jude Lee OS Project01 · JER_Jeremiah_BOOK_PROFILE_Theological_Filter_v0.2 · 내부 연구 방향 자료, 외부 이용허락 별도 확인 필요\n   * 사용 고지: 언약 배반과 심판, 거짓 안전과 회복의 긴장에 관한 예레미야서 전체의 해석 경계를 점검했습니다.\n\n연구 및 재서술 안내\n이 원고는 예레미야 2:14–22의 히브리어 본문을 중심으로 작성한 WORBS 기반 한국어 주석입니다. 실제 확인한 원문과 Tyndale Open Study Notes의 관련 항목을 참고하여 지리·역사·문학·신학 설명을 선택하고 재서술했습니다. 개역한글 번역문의 연속 인용은 사용하지 않았습니다. 원고의 독립 저작물·파생 저작물 여부는 단정하지 않습니다.\n\n라이선스\nOSHB는 CC BY 4.0(https://creativecommons.org/licenses/by/4.0/) 조건을 따르며, 기반 WLC 본문은 Public Domain으로 구별합니다. Tyndale Open Study Notes는 CC BY-SA 4.0(https://creativecommons.org/licenses/by-sa/4.0/) 조건에 따른 원저작자 표시와 변경 고지가 필요합니다. Project01 내부 연구 자료의 공개 이용 조건은 별도 확인 대상입니다. 원고 전체의 라이선스는 자료별 권리 검토가 끝나기 전에는 확정하지 않습니다."},{"schema":"JBC_PASSAGE_READER_COMMENTARY_v1","researchId":"JER_002_023_037_WORBS_READER_DRAFT_20261019","researchType":"WORBS","researchDepth":"CORE","sourcePath":"G:/내 드라이브/Jude_Lee_OS/01_PROJECTS/01_목회연구_WORBS_BICS/WORKING_COMMENTARY66_20261011/JER_002_023_037_WORBS_READER_DRAFT_20261019.md","sourceSha256":"3f3e92388ba7729bf2e7bcabdea2cd4fce9de224e4920f1a3868dc884a3bd3b0","passage":{"book":"jer","chapter":2,"v1":23,"v2":37,"ref":"예레미야 2:23–37"},"projectionStatus":"INTERNAL_READER_PROJECTION","professionalStatus":"CANDIDATE_REVIEW_ONLY","qualityStatus":"CANDIDATE_RESEARCH_REVIEW_REQUIRED","externalRelease":"NOT_AUTHORIZED","generatedByProject":"01_목회연구_WORBS_BICS","professionalAuthorityOwner":"01_목회연구_WORBS_BICS","title":"부인하는 입술과 드러나는 길","overview":["예레미야 2장의 첫머리에서 하나님은 광야의 관계를 기억하시며, 백성이 생수의 근원을 버리고 물을 담지 못하는 웅덩이를 팠다고 고발하셨습니다(2:1–13). 이어지는 말씀은 애굽과 앗수르에 기대는 정치적 선택, 멍에를 벗어 버린 듯 행동하는 언약의 배반, 변질된 포도나무와 지워지지 않는 얼룩을 보여 줍니다(2:14–22). 23절부터는 그 얼룩을 부인하는 백성 자신의 말이 전면에 나옵니다. 하나님은 그들의 주장과 실제 행로를 맞세우시고, 들나귀와 도둑, 신부의 장식, 무죄한 이들의 피, 실패한 외교라는 서로 다른 이미지로 하나의 현실을 드러내십니다."],"centralMessage":"이 부분의 중심 논지는 **하나님을 떠난 공동체가 자신의 불신실을 부인하면서 다른 신과 강대국을 의지하지만, 그 행로와 사회적 폭력과 반복되는 수치가 그 부인을 무너뜨린다**는 것입니다. 본문은 단순히 우상숭배를 금지하는 규칙을 되풀이하지 않습니다. 누가 참으로 자신들을 낳고 구원한 분인지, 위기의 순간 누구를 부르는지, 죄의 증거 앞에서 어떤 말을 하는지, 보호를 얻기 위해 어떤 길을 바꾸는지를 묻습니다. 3:1–5에서 혼인과 돌아옴의 언어가 더 날카롭게 이어지므로, 2:37은 큰 고발의 마지막이 아니라 다음 논증으로 넘어가는 경계이기도 합니다.","literaryStructure":[{"v1":23,"v2":23,"title":"더럽혀지지 않았다는 주장과 골짜기에 남은 행적"},{"v1":24,"v2":25,"title":"광야의 들나귀와 낯선 이들을 향한 고집"},{"v1":26,"v2":28,"title":"도둑의 수치와 나무·돌에게 맡긴 출생"},{"v1":29,"v2":30,"title":"하나님과 다투면서도 훈계를 받지 않는 백성"},{"v1":31,"v2":32,"title":"하나님을 황무지로 여기는 자유의 선언"},{"v1":33,"v2":34,"title":"사랑을 찾는 기술과 무죄한 이들의 피"},{"v1":35,"v2":37,"title":"죄가 없다는 마지막 항변과 실패할 외교의 길"}],"sections":[{"id":"jer2-23-23","v1":23,"v2":23,"title":"더럽혀지지 않았다는 주장과 골짜기에 남은 행적","paragraphs":["23절은 백성이 자기 입으로 내세우는 두 가지 부정에서 시작합니다. 자신은 더럽혀지지 않았으며 바알들을 따라가지 않았다는 주장입니다. 앞선 22절에서 아무리 씻어도 죄악의 얼룩이 하나님 앞에 남는다고 선언한 직후이기에, 이 부정은 더욱 선명한 모순을 만듭니다. 하나님은 그들의 내면을 추측하라고 하시지 않고, 골짜기에서 걸어온 길을 보라고 요구하십니다. ‘보라’와 ‘알라’는 명령은 자기평가가 아니라 행위의 증거를 살피라는 법정적 요청처럼 들립니다. 여기서 특정 골짜기의 지명은 제시되지 않습니다. 예루살렘 인근의 제의 장소들을 배경으로 생각할 여지는 있지만, 본문만으로 이 골짜기를 하나의 유적이나 한 번의 의식과 동일시할 수는 없습니다.","히브리어 **דֶּרֶךְ**(데레크, 길·행로)는 2:17–18에서 하나님이 인도하신 길과 애굽·앗수르로 향하는 길을 묻던 어휘 세계를 이어 줍니다. 길은 지도 위의 이동선인 동시에 지속적으로 택한 삶의 방향입니다. 자신은 바알들을 따르지 않았다고 말하는 백성에게 하나님은 실제로 어디를 향해 달려왔는지 보이십니다. 이어지는 빠른 어린 낙타의 이미지는 경로를 뒤섞으며 분주하게 움직이는 모습을 떠올리게 합니다. 동물의 동작을 인간의 특정 행위나 실제 순례 경로로 일대일 대응시키기보다, 말과 행동이 어긋난 끊임없는 추구를 나타내는 시적 비유로 읽는 것이 문맥에 맞습니다.","‘바알들’이라는 복수형은 한 장소에 하나의 신상만 있었다는 단순한 도식을 넘어, 여러 형태의 경쟁적 예배와 의존을 시사합니다. 그러나 이 한 절만으로 유다의 모든 주민이 동일한 제의에 참여했다고 단정할 수는 없습니다. 예언자는 공동체를 하나의 인격처럼 부르면서 그들의 공적 충성의 방향을 문제 삼습니다. 본문의 초점은 특정한 개인을 선정적으로 폭로하는 데 있지 않고, 하나님을 떠난 삶을 경건한 말로 가릴 수 없다는 데 있습니다."]},{"id":"jer2-24-25","v1":24,"v2":25,"title":"광야의 들나귀와 낯선 이들을 향한 고집","paragraphs":["24절은 광야에 익숙한 들나귀를 등장시킵니다. 냄새를 맡고 짝을 찾아 움직이는 동물의 강렬한 본능을 묘사하며, 그때에는 찾아 나선 자들이 어렵지 않게 만날 수 있다고 말합니다. 앞선 어린 낙타의 분주함이 여기서는 쉽게 멈추지 않는 갈망의 이미지로 심화됩니다. 이것은 동물의 번식 행동에 대한 완전한 자연사 설명이 아니라, 백성이 다른 신들을 좇는 열망을 비유하는 예언적 시입니다. 원문의 ‘그 달에’라는 표현을 현대 달력의 특정 월이나 제의 축제 날짜로 확정할 근거는 없습니다.","25절에서 하나님은 발이 벗겨지고 목이 마를 만큼 따라다니는 일을 멈추라고 말씀하십니다. 이 표현에는 길의 고단함이 들어 있지만, 반드시 맨발의 순례 행렬이나 한 번의 광야 이동을 기록하는 것은 아닙니다. ‘발’과 ‘목’은 스스로 택한 추구가 사람을 어떻게 소모시키는지 감각적으로 보여 줍니다. 백성은 이에 ‘소용없다’ 또는 ‘가망이 없다’는 뜻으로 읽히는 **נוֹאָשׁ**(노아시)라는 말로 응답하고, 낯선 이들을 사랑하므로 그 뒤를 따르겠다고 선언합니다. 23절의 부인과 25절의 인정이 서로 충돌합니다. 본문은 그 모순을 통해 문제가 정보 부족이나 우연한 실수가 아니라 굳어진 충성의 방향임을 드러냅니다.","여기서 ‘낯선 이들’은 문맥상 다른 신들과 잘못된 의존의 대상을 가리키는 은유적 표현입니다. 뒤의 애굽·앗수르 논쟁과 연결하여 외교적 의존의 차원도 함께 들을 수 있으나, 이 단어 하나를 곧 특정 제국의 사절단이나 특정 개인들로 좁혀서는 안 됩니다. 혼인과 불륜의 비유가 사용하는 강한 언어는 언약적 불신실을 고발하기 위한 것이며, 피해를 입은 개인의 성적 경험을 설명하거나 비난하는 문장이 아닙니다."]},{"id":"jer2-26-28","v1":26,"v2":28,"title":"도둑의 수치와 나무·돌에게 맡긴 출생","paragraphs":["26절은 붙잡힌 도둑이 당하는 수치에 이스라엘 집의 수치를 비유합니다. 중요한 것은 단지 죄가 있었다는 사실이 아니라, 그 죄가 드러났을 때에도 백성이 정직하게 돌아서지 않는다는 앞뒤 문맥입니다. 왕들과 고관들, 제사장들과 예언자들이 함께 열거됩니다. 통치와 행정, 예배와 말씀을 맡은 이들이 모두 고발의 범위 안에 들어옵니다. 따라서 이 본문을 지도층의 한 부류만 탓하거나 일반 백성만 비난하는 방식으로 단순화할 수 없습니다. 예언자가 묘사하는 것은 공동체의 방향을 잡아야 할 기관들이 함께 뒤틀린 상태입니다.","27절은 나무를 아버지라, 돌을 자신을 낳은 존재라 부르는 역전을 보여 줍니다. 나무와 돌은 우상을 만드는 재료를 떠올리게 하며, 창조하고 구원하신 하나님에게 돌려야 할 근원의 언어가 피조물에게 옮겨 간 현실을 드러냅니다. 히브리어 본문에는 돌에게 하는 말의 동사에서 쓰인 형태와 읽기 전승 사이의 차이가 나타납니다. 한국어 해설에서는 ‘나를 낳았다’와 ‘우리를 낳았다’ 같은 표현의 세부 차이를 무시할 수 없지만, 어느 쪽이든 근원을 잘못 부르는 전도가 논지의 중심입니다. 나무가 언제나 남성 신, 돌이 언제나 여성 신을 가리킨다는 고정된 대응표를 본문 자체가 제공하지는 않습니다.","‘등을 돌리고 얼굴을 돌리지 않았다’는 구절은 관계의 단절을 신체 방향으로 보여 줍니다. 2:23의 ‘길’이 행동의 방향이라면 여기서 ‘얼굴’은 누구를 향해 서 있는가의 문제입니다. 그런데 재난이 닥치면 그들은 하나님에게 일어나 구원해 달라고 외칩니다. 평소에는 하나님을 근원으로 인정하지 않으면서 위험할 때만 구원자로 부르는 모순입니다. 하나님은 28절에서 그들이 스스로 만든 신들이 어디 있는지 되물으십니다. 그 신들이 위기의 날에 구원할 수 있다면 일어나 보라는 반문은, 우상이 실제로 위기에서 아무 역할도 하지 못함을 폭로하는 수사적 도전입니다.","‘성읍의 수만큼 신들이 있다’는 표현은 유다의 예배적 분열과 광범한 우상 의존을 강조합니다. 그것을 각 도시의 신상 개수를 조사한 통계 자료처럼 읽어서는 안 됩니다. 신명기 32:37–38과 사사기 10:13–14에서 하나님이 다른 신들에게 구원을 요청해 보라고 하시는 말씀과 연결되지만, 각 본문이 말하는 역사적 순간은 구별해야 합니다. 예레미야의 독특한 강조는 위기 때 하나님을 부르는 언어와 평소의 충성이 서로 맞지 않는다는 점에 있습니다."]},{"id":"jer2-29-30","v1":29,"v2":30,"title":"하나님과 다투면서도 훈계를 받지 않는 백성","paragraphs":["29절의 ‘어찌하여 나와 다투느냐’는 질문은 앞선 고발을 언약적 논쟁의 자리로 다시 돌려놓습니다. 히브리어 **רִיב**(리브)는 다툼과 소송의 어휘 세계에 속합니다. 백성은 하나님을 향해 억울함을 제기하는 듯하지만, 하나님은 모두가 자신을 거역했다고 답하십니다. 2:5에서 조상들이 하나님에게 무슨 불의를 발견했느냐고 물으셨던 장면과 대응됩니다. 논쟁의 쟁점은 하나님의 신실하심에 대한 정당한 고발이 있는가, 아니면 공동체가 자기 책임을 뒤집어 말하는가입니다.","30절에서 하나님은 자녀들을 쳤으나 그들이 **מוּסָר**(무사르, 훈계·징계)를 받아들이지 않았다고 말씀하십니다. 이 단어는 단순한 체벌 기술이 아니라 잘못된 길에서 돌아서도록 하는 교정의 뜻을 가집니다. 본문은 징계가 있었음에도 배움이 일어나지 않았다고 진술합니다. 여기서 모든 재난을 하나님이 직접 주신 개인별 처벌로 해석하거나, 오늘의 폭력을 정당화하는 원칙을 도출할 수는 없습니다. 특정 언약 공동체의 역사에 대한 예언적 해석이라는 문맥이 중요합니다.","이어 백성의 칼이 선지자들을 삼켰다는 고발은 논쟁이 단순한 말다툼에 머물지 않았음을 보여 줍니다. 하나님 말씀을 전하는 사람들을 폭력으로 제거하는 행위는 스스로를 교정할 가능성을 차단합니다. 예레미야 26장은 선지자에게 가해진 위협과 우리야의 죽음을 보여 주어 이 고발이 책 전체에서 어떤 무게를 갖는지 드러냅니다. 다만 2:30의 모든 사건을 26장의 한 인물이나 한 날짜로 환원할 수는 없습니다. 예언서가 고발하는 것은 경고를 듣지 않는 태도가 역사 속에서 반복되어 왔다는 사실입니다."]},{"id":"jer2-31-32","v1":31,"v2":32,"title":"하나님을 황무지로 여기는 자유의 선언","paragraphs":["31절은 청중을 ‘이 세대’라고 직접 부르며 여호와의 말씀을 보라고 요구합니다. 하나님은 자신이 이스라엘에게 광야나 짙은 어둠의 땅이었느냐고 물으십니다. 2:6에서 하나님이 위험한 광야를 통과하도록 인도하셨던 기억을 떠올리면, 이 질문의 역설이 뚜렷해집니다. 생명의 길을 열어 주신 하나님을 백성은 오히려 자신을 가두고 메마르게 하는 존재처럼 취급하고 있습니다. 본문은 하나님의 실제 성품을 백성의 왜곡된 평가와 맞세웁니다.","‘우리는 마음대로 다닌다’ 혹은 ‘우리는 자유롭다’는 식으로 번역되는 히브리어 **רַדְנוּ**(라드누)의 정확한 뉘앙스에는 논의가 있습니다. 독립이나 자유로운 행동을 주장하는 읽기가 문맥과 잘 맞지만, 어형의 세부 의미를 하나의 현대적 정치 구호로 확정하기는 어렵습니다. 뒤따르는 ‘다시는 주께 오지 않겠다’는 선언은 적어도 관계를 끊겠다는 의사를 분명하게 합니다. 2:20에서 멍에를 꺾은 후 복종하지 않겠다고 말하던 백성의 태도가 다시 나타납니다. 하나님을 떠나는 일을 자유라고 부르는 동안, 그들은 이미 다른 신들과 제국의 힘에 매여 있다는 것이 이 장 전체의 아이러니입니다.","32절은 신부가 자신의 장식이나 혼인 때의 띠를 잊을 수 있겠느냐고 묻습니다. 그 시대 혼례의 모든 세부 풍속을 복원하지 않더라도, 신부에게 특별한 의미를 가진 장식을 잊는 일은 이례적이라는 비유의 힘을 이해할 수 있습니다. 그러나 하나님 백성은 셀 수 없는 날 동안 하나님을 잊었습니다. 2:2의 젊은 시절의 사랑과 신부의 기억이 여기서는 망각의 고발로 되돌아옵니다. ‘잊었다’는 말은 단순한 기억력 상실이 아니라, 언약 관계가 현재의 행동을 더 이상 이끌지 못하는 상태를 가리킵니다. 시편 106:21과 호세아 8:14에서도 구원의 하나님을 잊는 일이 예배와 역사적 선택의 문제로 제시됩니다."]},{"id":"jer2-33-34","v1":33,"v2":34,"title":"사랑을 찾는 기술과 무죄한 이들의 피","paragraphs":["33절에서 예언자는 백성이 ‘사랑을 찾기 위해’ 자기 길을 얼마나 능숙하게 꾸미는지 고발합니다. 앞서 2:25에서는 낯선 이들을 사랑하므로 그 뒤를 따르겠다고 했고, 이제 그 사랑을 얻는 기술이 문제 됩니다. 본문은 관계를 가리키는 혼인 은유를 사용하지만, 이것을 단순한 연애 감정의 문제가 아니라 하나님 대신 다른 대상에게 안전과 정체성을 맡기는 선택의 문제로 읽어야 합니다. 뒤이어 ‘악한 이들까지 네 길을 배운다’는 취지의 표현은 문법적 주어와 대상의 이해에 따라 번역의 뉘앙스가 달라질 수 있습니다. 확실한 것은 백성이 잘못된 길에서 수동적인 희생자로만 묘사되지 않고, 그 길을 적극적으로 익히고 넓혀 간다는 비판입니다.","34절은 이 모든 논쟁을 사회적 정의의 문제로 돌려놓습니다. 백성의 옷자락에서 무죄한 가난한 사람들의 피가 발견된다는 것입니다. 하나님을 떠난 신앙이 오직 예배 장소나 제의 행위의 문제로 끝나지 않음을 보여 줍니다. 힘없는 사람들의 생명이 침해되고, 그 흔적이 공동체의 옷에 남습니다. ‘가난한 이들’과 ‘무죄한 이들’은 하나님이 보호해야 한다고 말씀하신 이웃들입니다. 신명기 24:14–15와 예레미야 7:6에서 드러나는 사회적 책임과도 연결됩니다. 따라서 예언자의 언약 고발은 우상숭배와 불의를 서로 무관한 두 목록으로 나누지 않습니다.","‘굴을 뚫고 들어오는 도둑에게서 발견한 것도 아니다’라는 식의 구절은 히브리어 문장 연결이 난해한 부분입니다. 강도의 침입처럼 피 흘림을 정당화할 만한 상황이 아니었다는 대비로 읽는 견해가 있으나, 뒤의 짧은 표현을 어떻게 연결할지에 대해서는 논의가 남습니다. 그러므로 특정 법정 사건이나 범인의 행위를 확정적으로 재구성하기보다, 본문이 무고한 이들의 피를 명백한 죄의 증거로 제시한다는 사실에 집중해야 합니다. 2:22의 씻을 수 없는 얼룩은 이제 실제 피해자들의 피라는 훨씬 구체적인 윤리적 무게를 얻습니다."]},{"id":"jer2-35-37","v1":35,"v2":37,"title":"죄가 없다는 마지막 항변과 실패할 외교의 길","paragraphs":["35절에서 백성은 자신이 깨끗하며 하나님의 진노가 이미 떠났다고 주장합니다. 23절의 ‘더럽혀지지 않았다’는 부인이 단락 끝에서 ‘죄를 짓지 않았다’는 주장으로 다시 등장합니다. 하나님은 바로 그 말을 근거로 그들과 다투겠다고 선언하십니다. 예언의 논리는 단순히 하나님이 화가 나셨다는 것이 아닙니다. 죄를 인정하지 않는 자기변명이 회개와 관계 회복의 길을 가로막는다는 것입니다. 2:29에서 백성이 하나님과 다투는 듯했다면, 35절에서는 하나님이 그들의 거짓 무죄 주장에 맞서 심판의 논쟁을 계속하십니다.","36절은 다시 정치적 선택의 길을 소환합니다. 백성은 길을 바꾸려고 그토록 분주하게 움직이지만, 애굽 때문에도 앗수르 때문에 수치를 당했던 것처럼 수치를 당하리라는 경고를 듣습니다. 2:18에서 시홀과 유프라테스의 물을 마시려는 까닭을 물었던 질문이 이 지점에서 결말을 얻습니다. 예언자는 특정 외교 문서나 동맹 체결일을 제공하지 않습니다. 다만 강대국의 보호를 구하는 선택이 하나님을 대신하는 궁극적 신뢰가 될 때, 그 신뢰는 백성을 지탱하지 못한다고 선언합니다. 유다 말기의 외교적 압력과 앗수르·애굽 사이의 권력 변화는 역사적 배경이 되지만, 이 절 하나로 모든 사건을 한 왕의 정책에 배정할 수는 없습니다.","37절에서 백성은 두 손을 머리에 얹은 채 그곳을 떠날 것이라고 말씀하십니다. 이 자세는 슬픔과 수치, 좌절을 표현하는 고대의 몸짓으로 읽을 수 있습니다. 앞서 따라가던 길의 끝이 안전한 귀환이 아니라 굴욕적인 물러남으로 그려집니다. 그 이유는 하나님이 백성이 의지한 대상들을 거절하셨기 때문입니다. ‘그들로 말미암아 형통하지 못할 것’이라는 결론은 정치적 성공의 보편 법칙을 만드는 문장이 아니라, 이 예언이 문제 삼은 거짓 신뢰에 대한 판단입니다. 생수의 근원을 떠나 다른 물을 찾아 나섰던 공동체는 결국 그 물로 생명을 보장받지 못합니다.","이 단락은 부인에서 시작하여 수치로 끝납니다. 그러나 책 전체의 이야기에서는 이것이 마지막 말이 아닙니다. 곧 이어지는 3:1–5는 혼인 관계가 심각하게 훼손되었을 때 ‘돌아옴’을 어떻게 말할 수 있는지 질문하며, 3:6 이하에서는 돌아오라는 부름과 회복의 가능성을 더 길게 펼칩니다. 그렇다고 후속 회복의 약속을 앞당겨 2:23–37의 고발을 약화해서는 안 됩니다. 이 구간은 거짓 무죄 주장과 잘못된 의존의 실체를 충분히 드러내어, 이후의 돌아옴이 단순한 감정의 변화가 아니라 진실을 인정하는 관계의 전환임을 준비합니다."]}],"lexicalCards":[],"discoveries":[],"canonicalLinks":[],"theologicalSynthesis":[],"alternativeReadings":[{"title":"‘길’의 반복과 고발의 구조","paragraphs":["2:23의 골짜기에서의 행로, 2:25의 낯선 이들을 따르는 움직임, 2:33의 사랑을 찾는 길, 2:36의 길 바꾸기는 같은 이미지 영역에 속합니다. 앞선 2:6과 2:17에서 하나님이 인도하신 길과 대조하면, ‘길’은 여행 정보 이상의 언약적 충성을 나타냅니다. 이동과 정치적 선택과 예배의 방향이 서로 연결되지만, 본문이 제공하지 않는 실제 이동 경로를 지도에 그릴 수 있다는 뜻은 아닙니다."]},{"title":"들나귀의 비유와 문학적 긴장","paragraphs":["2:23–25는 분주한 어린 낙타, 갈망하는 들나귀, 목마른 발걸음이라는 이미지를 연속시킵니다. 비유의 초점은 통제할 수 없는 욕망과 반복되는 추구에 있으며, 동물의 생태적 세부를 역사적 의식의 증거로 바꾸지 않는 것이 중요합니다. 2:23의 부정과 2:25의 인정이 충돌하는 방식은 화자의 말이 얼마나 불안정한지를 보여 줍니다."]},{"title":"나무와 돌, 본문 전승의 세부","paragraphs":["2:27의 나무와 돌은 피조물에게 출생과 근원의 자리를 내어 준 예배의 역전을 드러냅니다. 로컬 히브리어 본문에는 돌에게 말하는 동사에서 자음 전승과 읽기 전승의 차이가 표시됩니다. 그러나 이것만으로 특정 고대 역본이 무엇을 읽었다고 단정할 수는 없습니다. 나무·돌의 성별 상징을 모든 고대 제의에 동일하게 적용하는 설명도 본문 증거를 넘어섭니다."]},{"title":"언약 논쟁과 교정의 거부","paragraphs":["2:29의 리브와 2:30의 무사르는 각각 논쟁과 훈계의 의미를 품습니다. 하나님이 일방적으로 침묵하는 백성을 벌하시는 장면이 아니라, 백성의 항변과 하나님의 반문, 반복된 경고의 거부가 이어지는 담화입니다. 2:35에서 죄가 없다는 말이 다시 등장하므로, 문제의 핵심은 죄를 감추는 언어와 교정을 거부하는 태도입니다. 26장의 선지자 박해 사건은 이 고발을 더 구체적으로 이해하게 하지만, 동일 사건이라는 직접 인용 관계는 아닙니다."]},{"title":"34절의 난해한 문장과 윤리적 초점","paragraphs":["무죄한 가난한 사람들의 피가 발견된다는 주장은 분명합니다. 다만 ‘굴을 뚫고 들어옴’과 뒤따르는 짧은 접속 표현을 어떻게 문장에 연결할지는 번역상 논의가 있습니다. 한 번의 특정 범죄 수사 기록으로 읽기보다, 부당한 피 흘림이 종교적 자기정당화와 양립할 수 없다는 예언의 윤리적 논지를 보존해야 합니다. 이는 7:5–7에서 나그네와 고아와 과부를 압제하지 말고 무죄한 피를 흘리지 말라는 요청과 강하게 연결됩니다."]},{"title":"앗수르와 애굽의 역사적 배경","paragraphs":["북왕국의 멸망과 남유다의 정치적 압박, 앗수르의 세력과 애굽의 영향력은 예레미야의 세계를 이해하는 중요한 배경입니다. 그러나 2:36–37은 특정 연도의 조약 명칭이나 외교 사절의 세부 동선을 알려 주지 않습니다. 예언자가 역사 속의 의존을 비판한다는 사실과 오늘의 모든 외교 행위를 금지한다는 주장은 다릅니다. 하나님을 대신하는 궁극적 안전의 근원으로 제국을 삼는 태도가 고발의 중심입니다."]},{"title":"2:23–3:5의 큰 문학적 단위","paragraphs":["실제로 확인한 Tyndale Open Study Notes는 2:23–3:5를 하나의 연속 단락으로 다루며, 들짐승·도둑·혼인 관계의 비유가 점층적으로 이어짐을 지적합니다. 이 원고는 Reader의 장별 범위를 존중하여 2:23–37을 독립 설명하되, 3:1–5와의 문학적 결속을 숨기지 않았습니다. 3:1의 돌아옴을 해석할 때 신명기 24:1–4의 이혼 규정과 3:12 이하의 회복 요청을 함께 살펴야 하며, 아직 읽지 않은 후속 단락의 결론을 현재 본문에 강제하지 않습니다."]}],"relatedResearch":[],"readerSources":[{"name":"Tyndale Open Study Notes","locator":"Tyndale Open Study Notes · Tyndale House Publishers · 예레미야 2:23–3:5 관련 항목, StudyNotes","license":"CC BY-SA 4.0"}],"notes":["연구 참고자료\n* Open Scriptures Hebrew Bible (OSHB) · Open Scriptures Hebrew Bible Project · 예레미야 2:23–37, JudeBible 로컬 히브리어 본문 v2.2 · CC BY 4.0\n   * 원자료: https://github.com/openscriptures/morphhb\n   * 변경 고지: 본문 어절과 읽기 전승 표시를 대조하고 문맥에 따라 한국어로 해설했습니다. 앱에서 생성된 표시 파일과 기반 원천을 구별합니다.\n* Westminster Leningrad Codex (WLC) · OSHB 기반 히브리어 본문 · 예레미야 2장 기반 본문 · Public Domain\n   * 기반 판본 안내: https://github.com/openscriptures/morphhb\n* Tyndale Open Study Notes · Tyndale House Publishers · 예레미야 2:23–3:5 관련 항목, StudyNotes.xml release 1.25 / Copyright © 2022 Tyndale House Publishers · CC BY-SA 4.0\n   * 원자료: http://www.tyndaleopenresources.com\n   * 저작권자 지정 고지: Adapted from Tyndale Open Study Notes. The original work by Tyndale House Publishers is available for free at http://www.tyndaleopenresources.com.\n   * 변경 고지: 해당 절의 문학적 구분과 우상숭배·사회적 불의·강대국 의존에 관한 주해를 참고하여 한국어 해설의 구조와 논증을 새롭게 작성했습니다. 원문을 연속 번역하거나 전재하지 않았습니다.\n* 예레미야 Book Profile · Jude Lee OS Project01 · JER_Jeremiah_BOOK_PROFILE_Theological_Filter_v0.2 · 내부 연구 방향 자료, 외부 이용허락 별도 확인 필요\n   * 사용 고지: 예레미야서의 언약 고발, 거짓 안전, 심판과 회복의 긴장을 해석하는 기준으로 확인했습니다.","연구 및 재서술 안내\n이 글은 예레미야 2:23–37의 히브리어 본문을 중심으로 작성한 WORBS 기반 한국어 주석입니다. 실제 확인한 Tyndale Open Study Notes의 관련 절별 항목과 Project01의 예레미야서 연구 방향을 참고하고, 본문 구조·문학적 연결·원어·역사문화·신학적 의미를 한국어 산문으로 재구성했습니다. 개역한글 번역문의 연속 인용은 사용하지 않았습니다. 원고 전체의 독립 저작물 또는 파생 저작물 여부는 임의로 확정하지 않습니다.","라이선스\nOSHB는 CC BY 4.0(https://creativecommons.org/licenses/by/4.0/) 조건을 따르며, 기반 WLC는 Public Domain으로 구별합니다. Tyndale Open Study Notes는 CC BY-SA 4.0(https://creativecommons.org/licenses/by-sa/4.0/) 조건에 따라 원저작자 표시와 변경 고지가 필요합니다. Project01 내부 자료의 외부 이용 조건은 별도 확인 대상입니다. 원고 전체의 라이선스는 자료별 권리검증을 마치기 전에는 확정하지 않습니다."],"sourceNotice":"연구 참고자료\n* Open Scriptures Hebrew Bible (OSHB) · Open Scriptures Hebrew Bible Project · 예레미야 2:23–37, JudeBible 로컬 히브리어 본문 v2.2 · CC BY 4.0\n   * 원자료: https://github.com/openscriptures/morphhb\n   * 변경 고지: 본문 어절과 읽기 전승 표시를 대조하고 문맥에 따라 한국어로 해설했습니다. 앱에서 생성된 표시 파일과 기반 원천을 구별합니다.\n* Westminster Leningrad Codex (WLC) · OSHB 기반 히브리어 본문 · 예레미야 2장 기반 본문 · Public Domain\n   * 기반 판본 안내: https://github.com/openscriptures/morphhb\n* Tyndale Open Study Notes · Tyndale House Publishers · 예레미야 2:23–3:5 관련 항목, StudyNotes.xml release 1.25 / Copyright © 2022 Tyndale House Publishers · CC BY-SA 4.0\n   * 원자료: http://www.tyndaleopenresources.com\n   * 저작권자 지정 고지: Adapted from Tyndale Open Study Notes. The original work by Tyndale House Publishers is available for free at http://www.tyndaleopenresources.com.\n   * 변경 고지: 해당 절의 문학적 구분과 우상숭배·사회적 불의·강대국 의존에 관한 주해를 참고하여 한국어 해설의 구조와 논증을 새롭게 작성했습니다. 원문을 연속 번역하거나 전재하지 않았습니다.\n* 예레미야 Book Profile · Jude Lee OS Project01 · JER_Jeremiah_BOOK_PROFILE_Theological_Filter_v0.2 · 내부 연구 방향 자료, 외부 이용허락 별도 확인 필요\n   * 사용 고지: 예레미야서의 언약 고발, 거짓 안전, 심판과 회복의 긴장을 해석하는 기준으로 확인했습니다.\n\n연구 및 재서술 안내\n이 글은 예레미야 2:23–37의 히브리어 본문을 중심으로 작성한 WORBS 기반 한국어 주석입니다. 실제 확인한 Tyndale Open Study Notes의 관련 절별 항목과 Project01의 예레미야서 연구 방향을 참고하고, 본문 구조·문학적 연결·원어·역사문화·신학적 의미를 한국어 산문으로 재구성했습니다. 개역한글 번역문의 연속 인용은 사용하지 않았습니다. 원고 전체의 독립 저작물 또는 파생 저작물 여부는 임의로 확정하지 않습니다.\n\n라이선스\nOSHB는 CC BY 4.0(https://creativecommons.org/licenses/by/4.0/) 조건을 따르며, 기반 WLC는 Public Domain으로 구별합니다. Tyndale Open Study Notes는 CC BY-SA 4.0(https://creativecommons.org/licenses/by-sa/4.0/) 조건에 따라 원저작자 표시와 변경 고지가 필요합니다. Project01 내부 자료의 외부 이용 조건은 별도 확인 대상입니다. 원고 전체의 라이선스는 자료별 권리검증을 마치기 전에는 확정하지 않습니다."}].forEach(function(r){a.push(r);});if(w.JBCResearch&&w.JBCResearch._done)w.JBCResearch._done("jer");})(window);
